import fs from 'node:fs';
import path from 'node:path';
import { execFileSync, spawnSync } from 'node:child_process';
import { randomUUID } from 'node:crypto';
import { canonical, DeliverError, internalDirectory, readRun, sha256, validateTaskPacket } from './state.mjs';
import { assertCurrentBinding } from './current-pm.mjs';
import { readPlanPolicy } from './project-state.mjs';
import { parseReviewReceipt } from './review.mjs';
import { parseVerificationResults, renderVerificationArtifacts } from './reporting.mjs';
import { parseStory, readStory, replaceStoryExecution } from './story.mjs';
import { environmentHandle } from './gates.mjs';
import { captureGitAnchor, snapshot } from './scope.mjs';

const OID = /^[0-9a-f]{40}(?:[0-9a-f]{24})?$/;
const HASH = /^[0-9a-f]{64}$/;
const RUN_ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
const fail = (message, code = 66) => { throw new DeliverError(message, code); };
const json = (value) => `${JSON.stringify(value, null, 2)}\n`;
const now = () => new Date().toISOString();
const stamp = () => now().replace('T', ' ').replace('Z', '').slice(0, 16);
const covers = (scope, rel) => scope === rel || rel.startsWith(`${scope}/`);

function git(root, args, { buffer = false, env = undefined } = {}) {
  try {
    return execFileSync('git', ['-C', root, ...args], {
      encoding: buffer ? undefined : 'utf8', stdio: ['ignore', 'pipe', 'pipe'], timeout: 30000,
      windowsHide: true, ...(env ? { env: { ...process.env, ...env } } : {}),
    });
  } catch (error) {
    fail(`Git cannot complete local integration: ${String(error.stderr || error.message).trim()}`);
  }
}

function rootPath(root) {
  try {
    const real = fs.realpathSync.native(root);
    const stat = fs.lstatSync(real);
    if (!stat.isDirectory() || stat.isSymbolicLink()) fail('integration root must be a real directory');
    return real;
  } catch (error) {
    if (error instanceof DeliverError) throw error;
    fail(`cannot access integration root: ${error.message}`);
  }
}

function commonRepository(root) {
  const value = String(git(root, ['rev-parse', '--git-common-dir'])).trim();
  return fs.realpathSync.native(path.resolve(root, value));
}

function branch(root) {
  const value = String(git(root, ['symbolic-ref', '--short', 'HEAD'])).trim();
  if (!value) fail('integration checkout must use a named branch');
  return value;
}

function head(root) { return String(git(root, ['rev-parse', '--verify', 'HEAD'])).trim(); }
function tree(root, commit = 'HEAD') { return String(git(root, ['rev-parse', `${commit}^{tree}`])).trim(); }

function statusPaths(root) {
  const records = String(git(root, ['status', '--porcelain=v1', '-z', '--untracked-files=all'])).split('\0').filter(Boolean);
  const paths = [];
  for (let index = 0; index < records.length; index++) {
    const item = records[index];
    if (item.length < 4) continue;
    const status = item.slice(0, 2);
    paths.push(item.slice(3));
    if ((status[0] === 'R' || status[0] === 'C') && records[index + 1]) paths.push(records[++index]);
  }
  return paths.filter((rel) => rel !== '.deliver' && !rel.startsWith('.deliver/'));
}

function assertClean(root) {
  const dirty = statusPaths(root);
  if (dirty.length) fail(`integration checkout has uncommitted project paths: ${dirty.sort().join(', ')}`);
  const indexTree = String(git(root, ['write-tree'])).trim();
  if (indexTree !== tree(root)) fail('integration checkout index differs from HEAD');
}

function assertOrdinaryIndex(root) {
  const rows = git(root, ['ls-files', '-v', '-z'], { buffer: true }).toString('utf8').split('\0').filter(Boolean);
  const hidden = rows.filter((row) => row[0] !== 'H').map((row) => row.slice(2));
  if (hidden.length) fail(`integration checkout has unsupported index flags: ${hidden.sort().join(', ')}`);
}

function protectedShape(anchor, root = true) {
  return {
    metadata_version: anchor.metadata_version,
    ...(root ? { ref: anchor.ref } : {}),
    protected_hash: anchor.protected_hash,
    submodules: Object.fromEntries(Object.entries(anchor.submodules || {})
      .map(([rel, nested]) => [rel, protectedShape(nested, false)])),
  };
}

const protectedIgnored = (rel) => /(^|\/)(?:AGENTS|CLAUDE)\.md$/.test(rel)
  || /(^|\/)\.(?:agents|codex)(?:\/|$)/.test(rel)
  || rel.endsWith('.sdd') || /(^|\/)\.specdd(?:\/|$)/.test(rel)
  || /(^|\/)(?:config|configs|contract|contracts)(?:[./]|$)/.test(rel);

function liveFingerprint(root, rel) {
  const file = path.join(root, rel);
  let stat;
  try { stat = fs.lstatSync(file); } catch (error) {
    if (error.code === 'ENOENT') return null;
    throw error;
  }
  if (stat.isSymbolicLink()) return `symlink:${sha256(fs.readlinkSync(file))}`;
  if (stat.isFile()) return `file:${stat.mode & 0o100 ? '755' : '644'}:${sha256(fs.readFileSync(file))}`;
  fail(`unsupported executable checkout path type: ${rel}`);
}

function protectedIgnoredEntries(root) {
  const output = git(root, ['ls-files', '--others', '--ignored', '--exclude-standard', '-z'], { buffer: true });
  const entries = Object.create(null);
  for (const rel of output.toString('utf8').split('\0').filter(Boolean)
    .filter((item) => item !== '.deliver' && !item.startsWith('.deliver/')).filter(protectedIgnored).sort()) {
    entries[rel] = liveFingerprint(root, rel);
  }
  return entries;
}

function parseTreeRows(root, commit, scopes, recursive = true) {
  const args = ['ls-tree', ...(recursive ? ['-r'] : []), '-z', commit, '--', ...scopes];
  const output = git(root, args, { buffer: true });
  return output.toString('utf8').split('\0').filter(Boolean).map((raw) => {
    const match = /^(\d{6}) (\w+) ([0-9a-f]+)\t(.+)$/.exec(raw);
    if (!match) fail('cannot parse committed integration manifest');
    return { mode: match[1], type: match[2], oid: match[3], rel: match[4] };
  });
}

function treeObjects(root, commit, scopes = ['.']) {
  return Object.fromEntries(parseTreeRows(root, commit, scopes).map((entry) => [entry.rel, entry]));
}

function exactTreeObject(root, commit, rel) {
  return parseTreeRows(root, commit, [rel], false).find((entry) => entry.rel === rel) || null;
}

function moduleRoot(root, rel, { required = false } = {}) {
  const candidate = path.join(root, rel);
  let stat;
  try { stat = fs.lstatSync(candidate); } catch (error) {
    if (error.code === 'ENOENT' && !required) return null;
    fail(`cannot access initialized submodule ${rel}: ${error.message}`);
  }
  if (!stat.isDirectory() || stat.isSymbolicLink()) {
    if (!required && stat.isDirectory()) return null;
    fail(`initialized submodule path is not a real directory: ${rel}`);
  }
  const real = fs.realpathSync.native(candidate);
  const relative = path.relative(root, real);
  if (relative === '..' || relative.startsWith(`..${path.sep}`) || path.isAbsolute(relative) || real !== path.resolve(candidate)) {
    fail(`initialized submodule escapes its checkout: ${rel}`);
  }
  if (fs.readdirSync(real).length === 0) {
    if (!required) return null;
    fail(`required submodule checkout is uninitialized: ${rel}`);
  }
  let top;
  try { top = String(git(real, ['rev-parse', '--show-toplevel'])).trim(); } catch {
    fail(`submodule checkout is not initialized safely: ${rel}`);
  }
  if (fs.realpathSync.native(top) !== real) fail(`submodule checkout has an unexpected Git root: ${rel}`);
  return real;
}

function initializedForLinks(root, links) {
  const result = Object.create(null);
  for (const rel of Object.keys(links).sort()) {
    const nested = moduleRoot(root, rel);
    if (nested) result[rel] = nested;
  }
  return result;
}

function checkoutObjectEntries(root, commit) {
  const entries = Object.create(null);
  for (const item of Object.values(treeObjects(root, commit))) entries[item.rel] = fingerprintBlob(root, item.mode, item.oid);
  return entries;
}

function buildCheckoutProof(root, commit, anchor = captureGitAnchor(root)) {
  const entries = checkoutObjectEntries(root, commit);
  const expectedLinks = Object.fromEntries(Object.entries(entries).filter(([, value]) => /^gitlink:[0-9a-f]+$/.test(value)));
  const currentEntries = checkoutObjectEntries(root, 'HEAD');
  const currentLinks = Object.fromEntries(Object.entries(currentEntries).filter(([, value]) => /^gitlink:[0-9a-f]+$/.test(value)));
  const initialized = initializedForLinks(root, { ...expectedLinks, ...currentLinks });
  const children = Object.create(null);
  for (const [rel, nestedRoot] of Object.entries(initialized)) {
    const match = /^gitlink:([0-9a-f]+)$/.exec(expectedLinks[rel] || '');
    if (!match) fail(`initialized submodule is absent from expected M: ${rel}`);
    if (!anchor.submodules?.[rel]) fail(`initialized submodule is absent from protected anchor: ${rel}`);
    children[rel] = buildCheckoutProof(nestedRoot, match[1], anchor.submodules[rel]);
  }
  return {
    version: 'whole-checkout-v1',
    tree: tree(root, commit),
    entries,
    protected_hash: anchor.protected_hash,
    protected_ignored: protectedIgnoredEntries(root),
    initialized: children,
  };
}

function validateCheckoutProofObjects(root, commit, proof) {
  if (!proof || proof.version !== 'whole-checkout-v1' || proof.tree !== tree(root, commit)
    || canonical(proof.entries) !== canonical(checkoutObjectEntries(root, commit))
    || !HASH.test(proof.protected_hash || '') || !proof.protected_ignored || Array.isArray(proof.protected_ignored)
    || !proof.initialized || Array.isArray(proof.initialized)) fail('invalid expected M checkout proof');
  for (const [rel, nestedProof] of Object.entries(proof.initialized)) {
    const match = /^gitlink:([0-9a-f]+)$/.exec(proof.entries[rel] || '');
    if (!match) fail(`expected initialized submodule is not an M gitlink: ${rel}`);
    validateCheckoutProofObjects(moduleRoot(root, rel, { required: true }), match[1], nestedProof);
  }
  return proof;
}

function verifyCheckoutProof(root, commit, proof, anchor = captureGitAnchor(root)) {
  validateCheckoutProofObjects(root, commit, proof);
  if (head(root) !== commit || tree(root) !== proof.tree) fail('executable checkout is not at its expected commit');
  assertClean(root);
  assertOrdinaryIndex(root);
  for (const [rel, identity] of Object.entries(proof.entries)) {
    if (!String(identity).startsWith('gitlink:') && liveFingerprint(root, rel) !== identity) {
      fail(`executable tracked bytes differ from M: ${rel}`);
    }
  }
  const links = Object.fromEntries(Object.entries(proof.entries).filter(([, value]) => /^gitlink:[0-9a-f]+$/.test(value)));
  const initialized = initializedForLinks(root, links);
  if (canonical(Object.keys(initialized).sort()) !== canonical(Object.keys(proof.initialized).sort())) {
    fail('initialized submodule set differs from prepared M checkout');
  }
  if (anchor.protected_hash !== proof.protected_hash
    || canonical(protectedIgnoredEntries(root)) !== canonical(proof.protected_ignored)) {
    fail('protected Git metadata changed in executable checkout');
  }
  for (const [rel, nestedProof] of Object.entries(proof.initialized)) {
    const match = /^gitlink:([0-9a-f]+)$/.exec(proof.entries[rel]);
    if (!anchor.submodules?.[rel]) fail(`initialized submodule is absent from executable protected anchor: ${rel}`);
    verifyCheckoutProof(initialized[rel], match[1], nestedProof, anchor.submodules[rel]);
  }
  return proof;
}

function executableProof(root, manifest, commit, checkoutProof) {
  if (head(root) !== commit || tree(root) !== tree(root, commit)) fail('integration executable checkout is not at the recorded commit');
  verifyCheckoutProof(root, commit, checkoutProof);
  const anchor = captureGitAnchor(root);
  const live = snapshot(root, manifest.scopes);
  const normalized = normalizeSnapshotGitlinks(root, manifest, live.entries, { strict: true, observedEntries: live.entries });
  const liveManifest = snapshotManifest(manifest, normalized);
  if (canonical(liveManifest) !== canonical(manifest)) fail('integration executable bytes differ from the recorded M manifest');
  return { anchor, snapshot_hash: live.hash };
}

function fingerprintBlob(root, mode, oid) {
  if (mode === '160000') return `gitlink:${oid}`;
  const bytes = git(root, ['cat-file', 'blob', oid], { buffer: true });
  if (mode === '120000') return `symlink:${sha256(bytes)}`;
  if (!['100644', '100755'].includes(mode)) fail(`unsupported committed mode in integration manifest: ${mode}`);
  return `file:${mode === '100755' ? '755' : '644'}:${sha256(bytes)}`;
}

function treeEntries(root, commit, scopes) {
  const result = Object.create(null);
  for (const item of parseTreeRows(root, commit, scopes)) result[item.rel] = fingerprintBlob(root, item.mode, item.oid);
  return result;
}

function sourceBindings(state) {
  return {
    packet: sha256(canonical(state.task.packet)),
    actor: state.pm_binding.actor,
    route: { story: state.pm_binding.story, story_path: state.pm_binding.story_path, branch: state.pm_binding.branch },
    contract_hash: state.pm_binding.contract_hash,
    execution_hash: state.pm_binding.execution_hash,
    receipts: {
      review: receiptIdentity(state.review),
      verification: receiptIdentity(state.verification),
      gates: state.gates.map((item) => receiptIdentity(item)),
    },
  };
}

function manifestFromEntries(entries, scopes, bindings) {
  return { entries, bindings: structuredClone(bindings), hash: sha256(canonical({ entries, bindings })), scopes };
}

function boundManifest(root, commit, packet, storyPath, bindings = {}) {
  const scopes = [...new Set([...packet.touches, ...packet.read_paths, ...packet.specs, storyPath, 'docs/plan.md', 'docs/approval.json'])].sort();
  return manifestFromEntries(committedEntries(root, commit, scopes), scopes, bindings);
}

function committedEntries(root, commit, scopes) {
  const committed = treeEntries(root, commit, scopes);
  for (const scope of scopes) {
    if (scope === '.' || Object.keys(committed).some((rel) => covers(scope, rel))) continue;
    const segments = scope.split('/');
    for (let index = 1; index < segments.length; index++) {
      const rel = segments.slice(0, index).join('/');
      const entry = exactTreeObject(root, commit, rel);
      if (!entry) break;
      if (entry.mode !== '160000') continue;
      committed[rel] = fingerprintBlob(root, entry.mode, entry.oid);
      const nestedRoot = moduleRoot(root, rel, { required: true });
      const childScope = segments.slice(index).join('/');
      for (const [name, identity] of Object.entries(committedEntries(nestedRoot, entry.oid, [childScope]))) {
        committed[`${rel}/${name}`] = identity;
      }
      break;
    }
  }
  const candidates = new Set(Object.keys(committed));
  const entries = Object.create(null);
  for (const rel of [...candidates].sort()) entries[rel] = committed[rel] ?? null;
  for (const scope of scopes) {
    if (![...candidates].some((rel) => covers(scope, rel))) entries[scope] = null;
  }
  return entries;
}

function snapshotManifest(committed, snapshotEntries) {
  const candidates = new Set(Object.keys(committed.entries));
  for (const rel of Object.keys(snapshotEntries)) if (committed.scopes.some((scope) => covers(scope, rel))) candidates.add(rel);
  const entries = Object.create(null);
  for (const rel of [...candidates].sort()) entries[rel] = snapshotEntries[rel] ?? null;
  return manifestFromEntries(entries, committed.scopes, committed.bindings);
}

function manifestMismatches(left, right) {
  const paths = new Set([...Object.keys(left.entries), ...Object.keys(right.entries)]);
  return [...paths].filter((rel) => (left.entries[rel] ?? null) !== (right.entries[rel] ?? null)).sort();
}

function childScopes(scopes, rel) {
  return scopes.flatMap((scope) => covers(scope, rel) ? ['.'] : covers(rel, scope) ? [scope.slice(rel.length + 1)] : []);
}

function subtree(entries, rel) {
  return Object.fromEntries(Object.entries(entries).filter(([name]) => name === rel || name.startsWith(`${rel}/`)));
}

function normalizeSnapshotGitlinks(root, manifest, suppliedEntries, { strict, observedEntries } = {}) {
  const normalized = { ...suppliedEntries };
  const observed = observedEntries || snapshot(root, manifest.scopes).entries;
  const links = Object.entries(manifest.entries).filter(([rel, identity], index, all) => /^gitlink:[0-9a-f]+$/.test(identity || '')
    && !all.some(([parent, parentIdentity]) => parent !== rel && rel.startsWith(`${parent}/`) && /^gitlink:[0-9a-f]+$/.test(parentIdentity || '')));
  for (const [rel, identity] of links) {
    const match = /^gitlink:([0-9a-f]+)$/.exec(identity || '');
    try {
      if (canonical(subtree(suppliedEntries, rel)) !== canonical(subtree(observed, rel))
        || !String(observed[rel] || '').startsWith(`${identity}:`)) fail(`initialized submodule snapshot changed: ${rel}`);
      const moduleRoot = fs.realpathSync.native(path.join(root, rel));
      if (String(git(moduleRoot, ['rev-parse', '--show-toplevel'])).trim() !== moduleRoot || head(moduleRoot) !== match[1]) {
        fail(`initialized submodule is not at M's gitlink: ${rel}`);
      }
      assertClean(moduleRoot);
      assertOrdinaryIndex(moduleRoot);
      const scopes = childScopes(manifest.scopes, rel);
      const nestedManifest = manifestFromEntries(committedEntries(moduleRoot, match[1], scopes), scopes, {});
      const nestedLive = snapshot(moduleRoot, scopes);
      const nestedNormalized = normalizeSnapshotGitlinks(moduleRoot, nestedManifest, nestedLive.entries, {
        strict: true, observedEntries: nestedLive.entries,
      });
      if (canonical(snapshotManifest(nestedManifest, nestedNormalized)) !== canonical(nestedManifest)) {
        fail(`initialized submodule bytes differ from M's gitlink: ${rel}`);
      }
      for (const name of Object.keys(normalized)) if (name.startsWith(`${rel}/`)) delete normalized[name];
      for (const [name, value] of Object.entries(nestedNormalized)) {
        const namespaced = `${rel}/${name}`;
        if (Object.hasOwn(manifest.entries, namespaced)) normalized[namespaced] = value;
      }
      normalized[rel] = identity;
    } catch (error) {
      if (strict) throw error;
    }
  }
  return normalized;
}

function probeMergeTree(root, integration, candidate) {
  const args = ['merge-tree', '--write-tree', integration, candidate];
  const started = now();
  const result = spawnSync('git', ['-C', root, ...args], {
    encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], timeout: 30000, windowsHide: true, maxBuffer: 1024 * 1024,
  });
  const stdout = String(result.stdout || '');
  const stderr = String(result.stderr || '');
  const expected = stdout.trim().split(/\s+/)[0];
  return {
    ok: result.status === 0 && !result.error && OID.test(expected),
    tree: result.status === 0 && !result.error && OID.test(expected) ? expected : null,
    log: `command: git ${args.join(' ')}\nstarted: ${started}\nexit: ${result.status ?? 'null'}\n\n[stdout]\n${stdout}\n[stderr]\n${stderr}`,
    attempt: {
      provenance: 'deliver-merge-tree-probe-v1', argv: ['git', '-C', root, ...args], git_version: String(git(root, ['--version'])).trim(),
      integration, candidate, status: result.status,
      signal: result.signal || null, error: result.error?.message || null, started_at: started, finished_at: now(),
      stdout_hash: sha256(stdout), stderr_hash: sha256(stderr),
    },
  };
}

function expectedMergeTree(root, integration, candidate) {
  const probe = probeMergeTree(root, integration, candidate);
  if (!probe.ok) fail('candidate does not form a clean merge');
  return probe.tree;
}

function integrationIdentity(record) {
  return sha256(canonical({
    commit: record.integration.commit,
    tree: record.integration.tree,
    manifest: record.manifest.hash,
  }));
}

function recordPath(root, id, { create = false } = {}) {
  if (!RUN_ID.test(id || '')) fail('integration record id must be a canonical run id');
  const directory = create ? internalDirectory(root, ['integrations']) : path.join(root, '.deliver', 'integrations');
  let stat;
  let real;
  try { stat = fs.lstatSync(directory); real = fs.realpathSync.native(directory); }
  catch (error) { fail(`integration records directory is unavailable: ${error.message}`); }
  const expected = path.join(root, '.deliver', 'integrations');
  if (!stat.isDirectory() || stat.isSymbolicLink() || real !== expected) fail('integration records directory is not canonical');
  return path.join(real, `${id}.json`);
}

function atomic(file, content) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const temp = `${file}.${process.pid}.${randomUUID()}.tmp`;
  const fd = fs.openSync(temp, 'wx', 0o600);
  try { fs.writeFileSync(fd, content); fs.fsyncSync(fd); } finally { fs.closeSync(fd); }
  try { fs.renameSync(temp, file); } finally { try { fs.unlinkSync(temp); } catch {} }
}

function recordHash(record) { return sha256(canonical(record)); }

function expectedReporting(scale, requested) {
  if (['large', 'regulated'].includes(scale)) return 'required';
  if (scale === 'standard' && requested) return 'requested';
  return 'skipped';
}

function preparationIdentity(record) {
  return sha256(canonical({
    source_run_id: record.source.run_id,
    candidate: record.source.candidate,
    base: record.integration.base,
    destination_branch: record.destination.branch,
    reporting_requested: record.reporting_requested,
    reporting: record.reporting,
    merge_token: record.integration.token,
    base_anchor: sha256(canonical(record.integration.base_anchor)),
    base_checkout_proof: sha256(canonical(record.integration.base_checkout_proof)),
    expected_tree: record.integration.expected_tree,
    manifest: record.integration.manifest?.hash || null,
    checkout_proof: record.integration.checkout_proof ? sha256(canonical(record.integration.checkout_proof)) : null,
    failed_probe: record.integration.failure?.identity || null,
  }));
}

function validateRecord(record) {
  if (!record || typeof record !== 'object' || Array.isArray(record) || !RUN_ID.test(record.id || '')) {
    fail('integration record id must be a canonical run id');
  }
  if (!record || typeof record !== 'object' || Array.isArray(record) || record.schema_version !== 1
    || record.kind !== 'local-integration-v1'
    || !record.source || record.source.run_id !== record.id || !record.destination || !record.integration || !record.evidence
    || !record.source.manifest || !record.source.snapshot_manifest
    || !record.report || !record.closure || !record.handoff
    || typeof record.source.root !== 'string' || !path.isAbsolute(record.source.root)
    || typeof record.source.run_path !== 'string' || !path.isAbsolute(record.source.run_path)
    || path.basename(record.source.run_path) !== `${record.id}.json`
    || !HASH.test(record.source.snapshot_hash || '') || !HASH.test(record.source.contract_hash || '') || !HASH.test(record.source.execution_hash || '')
    || !OID.test(record.source.candidate) || !OID.test(record.integration.base)
    || !record.integration.base_anchor || typeof record.integration.base_anchor !== 'object' || Array.isArray(record.integration.base_anchor)
    || !record.integration.base_checkout_proof || typeof record.integration.base_checkout_proof !== 'object'
    || Array.isArray(record.integration.base_checkout_proof)
    || (record.integration.commit !== null && !OID.test(record.integration.commit))
    || !['prepared', 'failed', 'adopted'].includes(record.integration.status)
    || !Array.isArray(record.evidence.gates) || !['required', 'requested', 'skipped'].includes(record.reporting)
    || typeof record.reporting_requested !== 'boolean'
    || !Number.isSafeInteger(record.revision) || record.revision < 0
    || !record.plan || !['tiny', 'small', 'standard', 'large', 'regulated'].includes(record.plan.scale)
    || record.reporting !== expectedReporting(record.plan.scale, record.reporting_requested)
    || !record.preparation || record.preparation.identity !== preparationIdentity(record)
    || typeof record.destination.root !== 'string' || !path.isAbsolute(record.destination.root)
    || typeof record.destination.common_repository !== 'string' || !path.isAbsolute(record.destination.common_repository)) {
    fail('invalid local integration record');
  }
  if (typeof record.evidence.source_reusable !== 'boolean' || !Array.isArray(record.evidence.reuse_mismatches)
    || !Array.isArray(record.evidence.gate_history) || !Array.isArray(record.evidence.review_history)
    || !Array.isArray(record.evidence.verification_history) || !Array.isArray(record.evidence.finalization_history)) {
    fail('invalid integration evidence history');
  }
  for (const manifest of [record.source.manifest, record.source.snapshot_manifest, record.integration.manifest].filter(Boolean)) {
    if (!manifest.entries || typeof manifest.entries !== 'object' || Array.isArray(manifest.entries)
      || !manifest.bindings || typeof manifest.bindings !== 'object' || Array.isArray(manifest.bindings)
      || !Array.isArray(manifest.scopes) || !manifest.scopes.every((item) => typeof item === 'string') || !HASH.test(manifest.hash || '')
      || manifest.hash !== sha256(canonical({ entries: manifest.entries, bindings: manifest.bindings }))) fail('invalid integration manifest');
  }
  if (record.integration.status === 'adopted' && (!record.integration.manifest || !record.integration.anchor
    || !record.integration.checkout_proof || record.manifest?.hash !== record.integration.manifest.hash
    || !HASH.test(record.integration.executable_snapshot_hash || ''))) {
    fail('adopted integration lacks durable M proof');
  }
  if (record.integration.status === 'prepared' && (!RUN_ID.test(record.integration.token || '')
    || !OID.test(record.integration.expected_tree || '') || !record.integration.manifest
    || !record.integration.checkout_proof || record.integration.failure !== null)) {
    fail('prepared integration record is incomplete');
  }
  if (record.integration.status === 'failed' && (!record.integration.failure || record.integration.commit !== null
    || record.integration.token !== null || record.integration.expected_tree !== null || record.integration.manifest !== null
    || record.integration.checkout_proof !== null || !hasReceiptIdentity(record.integration.failure))) fail('failed integration probe claims an M');
  validateTaskPacket(record.source.packet);
  return record;
}

export function readIntegrationRecord(recordArg, cwd = process.cwd()) {
  const lexical = path.resolve(cwd, recordArg);
  let stat;
  try { stat = fs.lstatSync(lexical); } catch (error) { fail(`cannot read integration record: ${error.message}`); }
  if (!stat.isFile() || stat.isSymbolicLink() || stat.size > 8 * 1024 * 1024) fail('integration record must be a bounded regular file');
  let value;
  try { value = JSON.parse(fs.readFileSync(lexical, 'utf8')); } catch { fail('invalid JSON in integration record'); }
  const record = validateRecord(value);
  const file = fs.realpathSync.native(lexical);
  if (file !== lexical || record.id !== record.source.run_id
    || recordPath(rootPath(record.destination.root), record.id) !== file) fail('integration record path does not match its source run and destination checkout');
  return { file, record, hash: recordHash(record) };
}

function withRecord(recordArg, expectedHash, mutate, cwd = process.cwd()) {
  const loaded = readIntegrationRecord(recordArg, cwd);
  if (!HASH.test(expectedHash || '') || loaded.hash !== expectedHash) fail('integration record hash is missing or stale');
  const lock = `${loaded.file}.lock`;
  let fd;
  try { fd = fs.openSync(lock, 'wx', 0o600); } catch (error) {
    if (error.code === 'EEXIST') fail('integration record is locked');
    throw error;
  }
  try {
    const current = readIntegrationRecord(loaded.file);
    if (current.hash !== expectedHash) fail('integration record changed concurrently');
    assertRecordSource(current.record);
    validateIntegrationProofs(current.record);
    const result = mutate(current.record, current.file);
    current.record.revision += 1;
    current.record.updated_at = now();
    validateRecord(current.record);
    atomic(current.file, json(current.record));
    return { file: current.file, record: current.record, hash: recordHash(current.record), result };
  } finally {
    fs.closeSync(fd);
    try { fs.unlinkSync(lock); } catch {}
  }
}

function receiptIdentity(value) { return sha256(canonical(value)); }

function hasReceiptIdentity(value) {
  if (!value || !HASH.test(value.identity || '')) return false;
  const { identity, ...body } = value;
  return identity === receiptIdentity(body);
}

function assertSourceRun(state) {
  if (state.phase !== 'finished' || state.pm_binding?.format !== 'current' || !state.completion_snapshot) {
    fail('local integration requires a finished current-bound source run');
  }
  assertCurrentBinding(state);
  if (state.review?.status !== 'PASS' || state.review.findings.some((item) => !item.resolved && item.severity !== 'minor')
    || state.verification?.criteria.some((item) => item.status !== 'PASS')) fail('source C lacks complete independent evidence');
  if (state.verification.verifier === state.task.builder || state.verification.verifier === state.review.reviewer) {
    fail('current source verifier must differ from builder and reviewer');
  }
  if (state.git_anchor?.head !== state.commit_adoption?.history?.at(-1)?.commit) fail('source C is not the final adopted candidate');
}

function assertRecordSource(record) {
  const loaded = readRun(record.source.run_path);
  const state = loaded.state;
  assertSourceRun(state);
  if (state.run_id !== record.source.run_id || state.project_root !== record.source.root
    || state.pm_binding.story !== record.source.story || state.pm_binding.story_path !== record.source.story_path
    || state.pm_binding.contract_hash !== record.source.contract_hash || state.pm_binding.execution_hash !== record.source.execution_hash
    || state.pm_binding.actor !== record.source.actor || state.pm_binding.branch !== record.source.branch
    || state.git_anchor.head !== record.source.candidate || tree(state.project_root, record.source.candidate) !== record.source.tree
    || state.completion_snapshot.hash !== record.source.snapshot_hash
    || canonical(state.task.packet) !== canonical(record.source.packet)
    || canonical(state.counters) !== canonical(record.source.counters)
    || record.source.review.identity !== receiptIdentity(state.review)
    || record.source.verification.identity !== receiptIdentity(state.verification)
    || canonical(record.source.gates) !== canonical(state.gates.map((item) => ({ ...item, identity: receiptIdentity(item) })))) {
    fail('integration record no longer matches immutable source C');
  }
  const policy = readPlanPolicy(state.project_root);
  if ((policy?.scale || 'standard') !== record.plan.scale || policy?.integrationBranch !== record.plan.integration_branch
    || state.pm_binding.plan_digest !== record.plan.approval_digest
    || record.destination.branch !== record.plan.integration_branch
    || commonRepository(state.project_root) !== record.destination.common_repository) {
    fail('integration record no longer matches the approved plan or repository');
  }
  if (head(state.project_root) !== record.source.candidate || branch(state.project_root) !== record.source.branch) fail('finished source checkout no longer remains at C');
  const manifest = boundManifest(state.project_root, record.source.candidate, state.task.packet,
    state.pm_binding.story_path, sourceBindings(state));
  const normalizedSource = normalizeSnapshotGitlinks(state.project_root, manifest, state.completion_snapshot.entries, { strict: false });
  const sourceSnapshotManifest = snapshotManifest(manifest, normalizedSource);
  if (canonical(manifest) !== canonical(record.source.manifest)
    || canonical(sourceSnapshotManifest) !== canonical(record.source.snapshot_manifest)) {
    fail('integration record no longer matches immutable source manifests');
  }
  if (record.integration.status === 'failed') {
    if (!hasReceiptIdentity(record.integration.failure)) fail('failed merge probe identity is invalid');
    validateInternalLog(record, record.integration.failure);
  }
  return state;
}

export function prepareLocalIntegration(runArg, { integrationRoot = process.cwd(), verificationReport = false } = {}, cwd = process.cwd()) {
  const loaded = readRun(runArg, cwd);
  const state = loaded.state;
  assertSourceRun(state);
  const sourceRoot = rootPath(state.project_root);
  integrationRoot = rootPath(integrationRoot);
  if (commonRepository(sourceRoot) !== commonRepository(integrationRoot)) fail('source and integration checkouts are not in the same repository');
  const policy = readPlanPolicy(sourceRoot);
  const scale = policy?.scale || 'standard';
  const integrationBranch = policy?.integrationBranch;
  if (!integrationBranch || branch(integrationRoot) !== integrationBranch) fail('check out the approved integration branch before preparing a merge');
  assertClean(integrationRoot);
  assertOrdinaryIndex(integrationRoot);
  const base = head(integrationRoot);
  const baseAnchor = captureGitAnchor(integrationRoot);
  const baseCheckoutProof = buildCheckoutProof(integrationRoot, base, baseAnchor);
  verifyCheckoutProof(integrationRoot, base, baseCheckoutProof, baseAnchor);
  if (branch(sourceRoot) !== state.pm_binding.branch || head(sourceRoot) !== state.git_anchor.head) fail('source checkout no longer identifies candidate C');
  const candidate = state.git_anchor.head;
  try {
    execFileSync('git', ['-C', integrationRoot, 'merge-base', '--is-ancestor', candidate, base], { stdio: 'ignore' });
    fail('candidate C is already an ancestor of the integration branch');
  } catch (error) { if (error instanceof DeliverError) throw error; }
  const sourceManifest = boundManifest(sourceRoot, candidate, state.task.packet, state.pm_binding.story_path, sourceBindings(state));
  const normalizedSource = normalizeSnapshotGitlinks(sourceRoot, sourceManifest, state.completion_snapshot.entries, { strict: false });
  const sourceSnapshotManifest = snapshotManifest(sourceManifest, normalizedSource);
  const sourceMismatches = manifestMismatches(sourceManifest, sourceSnapshotManifest);
  const governance = new Set([state.pm_binding.story_path, 'docs/plan.md', 'docs/approval.json']);
  const governanceDrift = sourceMismatches.filter((rel) => governance.has(rel));
  if (governanceDrift.length) fail(`approved story or plan bytes differ from candidate C: ${governanceDrift.join(', ')}`);
  const reportingRequested = scale === 'standard' && verificationReport === true;
  const reporting = expectedReporting(scale, reportingRequested);
  const id = state.run_id;
  const file = recordPath(integrationRoot, id, { create: true });
  if (fs.existsSync(file)) {
    const existing = readIntegrationRecord(file);
    assertRecordSource(existing.record);
    validateIntegrationProofs(existing.record);
    if (existing.record.source.run_id !== state.run_id || existing.record.source.candidate !== candidate
      || existing.record.destination.root !== integrationRoot || existing.record.reporting !== reporting
      || existing.record.reporting_requested !== reportingRequested) {
      fail('existing integration preparation does not match this source run or reporting contract');
    }
    if (existing.record.integration.status === 'prepared') {
      if (head(integrationRoot) !== existing.record.integration.base) fail('prepared integration base is no longer current');
      verifyCheckoutProof(integrationRoot, existing.record.integration.base, existing.record.integration.base_checkout_proof);
      if (expectedMergeTree(integrationRoot, base, candidate) !== existing.record.integration.expected_tree) fail('prepared clean merge tree changed');
    }
    return { file, record: existing.record, hash: existing.hash, resumed: true };
  }
  const probe = probeMergeTree(integrationRoot, base, candidate);
  const mergedManifest = probe.ok
    ? boundManifest(integrationRoot, probe.tree, state.task.packet, state.pm_binding.story_path, sourceManifest.bindings)
    : null;
  const checkoutProof = probe.ok ? buildCheckoutProof(integrationRoot, probe.tree) : null;
  const mergeGovernanceDrift = mergedManifest ? manifestMismatches(sourceManifest, mergedManifest).filter((rel) => governance.has(rel)) : [];
  if (mergeGovernanceDrift.length) fail(`clean composition changes approved story or plan bytes: ${mergeGovernanceDrift.join(', ')}`);
  const review = { ...structuredClone(state.review), identity: receiptIdentity(state.review) };
  const verification = { ...structuredClone(state.verification), identity: receiptIdentity(state.verification) };
  let failure = null;
  if (!probe.ok) {
    const logDir = internalDirectory(integrationRoot, ['logs', `integration-${id}`]);
    const logFile = path.join(logDir, `merge-tree-${randomUUID()}.log`);
    fs.writeFileSync(logFile, probe.log, { flag: 'wx', mode: 0o600 });
    failure = { ...probe.attempt, log_path: path.relative(integrationRoot, logFile).split(path.sep).join('/'), log_hash: sha256(probe.log) };
    failure.identity = receiptIdentity(failure);
  }
  const sourceReusable = Boolean(mergedManifest) && sourceMismatches.length === 0
    && manifestMismatches(sourceManifest, mergedManifest).length === 0;
  const record = {
    schema_version: 1,
    kind: 'local-integration-v1',
    id,
    revision: 0,
    created_at: now(),
    updated_at: now(),
    source: {
      run_id: state.run_id, run_path: loaded.file, root: sourceRoot, story: state.pm_binding.story,
      story_path: state.pm_binding.story_path, contract_hash: state.pm_binding.contract_hash,
      execution_hash: state.pm_binding.execution_hash, candidate, tree: tree(sourceRoot, candidate),
      snapshot_hash: state.completion_snapshot.hash, builder: state.task.builder,
      actor: state.pm_binding.actor, branch: state.pm_binding.branch,
      packet: structuredClone(state.task.packet), counters: structuredClone(state.counters),
      review, verification, gates: state.gates.map((item) => ({ ...structuredClone(item), identity: receiptIdentity(item) })),
      manifest: sourceManifest, snapshot_manifest: sourceSnapshotManifest,
    },
    plan: { scale, integration_branch: integrationBranch, approval_digest: state.pm_binding.plan_digest },
    destination: { root: integrationRoot, common_repository: commonRepository(integrationRoot), branch: integrationBranch },
    integration: {
      status: probe.ok ? 'prepared' : 'failed', token: probe.ok ? randomUUID() : null, base, candidate,
      base_anchor: baseAnchor, base_checkout_proof: baseCheckoutProof, expected_tree: probe.tree,
      manifest: mergedManifest, checkout_proof: checkoutProof, failure,
      commit: null, tree: null, anchor: null, executable_snapshot_hash: null, adopted_at: null,
    },
    manifest: mergedManifest,
    reporting,
    reporting_requested: reportingRequested,
    preparation: { identity: null },
    evidence: {
      source_reusable: sourceReusable,
      reuse_mismatches: [...new Set([...sourceMismatches, ...(mergedManifest ? manifestMismatches(sourceManifest, mergedManifest) : [])])].sort(),
      snapshot_hash: null, gates: [], gate_history: [], review: null, review_history: [], verification: null,
      verification_history: [], finalization_history: [], finalized: false, finalized_at: null,
      effective_review_identity: null, effective_verification_identity: null,
    },
    report: { pending: null, commit: null, proof: null },
    closure: { pending: null, commit: null, proof: null, execution_hash: null },
    handoff: { pending: null, commit: null, proof: null, path: `docs/handoff/${state.pm_binding.actor}.md` },
  };
  record.preparation.identity = preparationIdentity(record);
  atomic(file, json(record));
  return { file, record, hash: recordHash(record), resumed: false };
}

function assertIntegrationHead(record, { requireCommit = true } = {}) {
  const root = rootPath(record.destination.root);
  if (commonRepository(root) !== record.destination.common_repository || branch(root) !== record.destination.branch) fail('integration checkout identity or branch changed');
  if (requireCommit && head(root) !== record.integration.commit) fail('integration checkout is not at recorded M');
  assertClean(root);
  return root;
}

function destinationRoot(record) {
  const root = rootPath(record.destination.root);
  if (commonRepository(root) !== record.destination.common_repository || branch(root) !== record.destination.branch) {
    fail('integration checkout identity or branch changed');
  }
  return root;
}

export function adoptLocalIntegration(recordArg, { expectedRecordHash, token, commit } = {}, cwd = process.cwd()) {
  return withRecord(recordArg, expectedRecordHash, (record) => {
    if (record.integration.status !== 'prepared' || token !== record.integration.token || !OID.test(commit || '')) fail('merge adoption token or commit is invalid');
    const root = rootPath(record.destination.root);
    if (branch(root) !== record.destination.branch || head(root) !== commit) fail('integration checkout is not at the supplied merge commit');
    const parents = String(git(root, ['rev-list', '--parents', '-n', '1', commit])).trim().split(/\s+/);
    if (parents.length !== 3 || parents[1] !== record.integration.base || parents[2] !== record.source.candidate) {
      fail('local integration must be the prepared no-ff merge of I and C');
    }
    if (expectedMergeTree(root, record.integration.base, record.source.candidate) !== record.integration.expected_tree) {
      fail('prepared clean merge proof no longer matches I and C');
    }
    if (tree(root, commit) !== record.integration.expected_tree) fail('actual merge tree differs from the prepared clean composition');
    const manifest = boundManifest(root, commit, record.source.packet, record.source.story_path, record.integration.manifest.bindings);
    if (canonical(manifest) !== canonical(record.integration.manifest)) fail('actual M manifest differs from its prepared composition');
    const proof = executableProof(root, manifest, commit, record.integration.checkout_proof);
    if (canonical(protectedShape(proof.anchor)) !== canonical(protectedShape(record.integration.base_anchor))) {
      fail('protected Git metadata changed between integration preparation and adoption');
    }
    record.integration.status = 'adopted';
    record.integration.commit = commit;
    record.integration.tree = tree(root, commit);
    record.integration.anchor = proof.anchor;
    record.integration.executable_snapshot_hash = proof.snapshot_hash;
    record.integration.adopted_at = now();
    record.manifest = record.integration.manifest;
    record.evidence.snapshot_hash = integrationIdentity(record);
    return record.integration;
  }, cwd);
}

function recheckM(record) {
  if (record.integration.status !== 'adopted') fail('actual integration M has not been adopted');
  const root = assertIntegrationHead(record);
  if (tree(root) !== record.integration.tree) fail('integration tree changed after adoption');
  const parents = String(git(root, ['rev-list', '--parents', '-n', '1', record.integration.commit])).trim().split(/\s+/);
  if (parents.length !== 3 || parents[1] !== record.integration.base || parents[2] !== record.source.candidate
    || expectedMergeTree(root, record.integration.base, record.source.candidate) !== record.integration.expected_tree
    || record.integration.tree !== record.integration.expected_tree) fail('recorded M is no longer the exact clean I plus C composition');
  const manifest = boundManifest(root, record.integration.commit, record.source.packet, record.source.story_path,
    record.integration.manifest.bindings);
  if (canonical(manifest) !== canonical(record.integration.manifest)) fail('integration manifest changed after adoption');
  if (integrationIdentity(record) !== record.evidence.snapshot_hash) fail('integration evidence snapshot identity is invalid');
  return root;
}

function assertExecutableM(record) {
  const root = recheckM(record);
  const proof = executableProof(root, record.integration.manifest, record.integration.commit, record.integration.checkout_proof);
  if (canonical(proof.anchor) !== canonical(record.integration.anchor)
    || proof.snapshot_hash !== record.integration.executable_snapshot_hash) {
    fail('integration executable checkout or protected metadata differs from adopted M');
  }
  return root;
}

function invalidateFinalization(record, reason) {
  if (!record.evidence.finalized) return;
  record.evidence.finalization_history.push({
    at: now(), reason, finalized_at: record.evidence.finalized_at,
    snapshot_hash: record.evidence.snapshot_hash,
    review_identity: record.evidence.effective_review_identity,
    verification_identity: record.evidence.effective_verification_identity,
    gates: record.evidence.gates.map((item) => item.identity),
  });
  record.evidence.finalized = false;
  record.evidence.finalized_at = null;
  record.evidence.effective_review_identity = null;
  record.evidence.effective_verification_identity = null;
}

function validateInternalLog(record, receipt) {
  const rel = receipt?.log_path;
  const directory = `.deliver/logs/integration-${record.id}`;
  if (typeof rel !== 'string' || path.posix.dirname(rel) !== directory
    || !/^[A-Za-z0-9][A-Za-z0-9._-]{0,200}\.log$/.test(path.posix.basename(rel)) || !HASH.test(receipt.log_hash || '')) {
    fail('integration evidence log path or hash is invalid');
  }
  const root = rootPath(record.destination.root);
  const file = path.join(root, ...rel.split('/'));
  let stat;
  try { stat = fs.lstatSync(file); } catch (error) { fail(`integration evidence log is unreadable: ${error.message}`); }
  if (!stat.isFile() || stat.isSymbolicLink() || stat.size > 4 * 1024 * 1024
    || fs.realpathSync.native(file) !== file) fail('integration evidence log must be a bounded canonical regular file');
  const bytes = fs.readFileSync(file);
  if (sha256(bytes) !== receipt.log_hash) fail('integration evidence log bytes changed');
}

export function runIntegrationGate(recordArg, { expectedRecordHash, name } = {}, cwd = process.cwd()) {
  return withRecord(recordArg, expectedRecordHash, (record) => {
    const command = record.source.packet.commands?.[name];
    if (typeof command !== 'string') fail('integration gate name is not declared by the source task');
    const root = assertExecutableM(record);
    const logDir = internalDirectory(root, ['logs', `integration-${record.id}`]);
    const log = path.join(logDir, `${name}-${randomUUID()}.log`);
    const started = now();
    const result = spawnSync(command, { cwd: root, shell: true, encoding: 'utf8', timeout: 10 * 60 * 1000, maxBuffer: 1024 * 1024, windowsHide: true });
    let stable = true;
    let proofError = null;
    try { assertExecutableM(record); } catch (error) { stable = false; proofError = error.message; }
    const environmentAdditionsHash = sha256(canonical({}));
    const receipt = {
      provenance: 'deliver-integration-gate-v1', name, command, integration_commit: record.integration.commit,
      snapshot_hash: record.evidence.snapshot_hash, status: result.status === 0 && !result.error && stable ? 'PASS' : 'FAIL',
      cwd: '.', environment_keys: [], environment_additions_hash: environmentAdditionsHash,
      environment_hash: environmentHandle(root, environmentAdditionsHash),
      exit_code: result.status, signal: result.signal || null, error: result.error?.message || proofError,
      started_at: started, finished_at: now(),
      output: { stdout_bytes: Buffer.byteLength(result.stdout || ''), stderr_bytes: Buffer.byteLength(result.stderr || '') },
    };
    const logText = `command: ${command}\nstarted: ${started}\nexit: ${result.status}\n\n[stdout]\n${result.stdout || ''}\n[stderr]\n${result.stderr || ''}`;
    fs.writeFileSync(log, logText, { flag: 'wx', mode: 0o600 });
    receipt.log_path = path.relative(root, log).split(path.sep).join('/');
    receipt.log_hash = sha256(logText);
    receipt.identity = receiptIdentity(receipt);
    invalidateFinalization(record, `gate ${name} changed`);
    const previous = record.evidence.gates.find((item) => item.name === name);
    if (previous) record.evidence.gate_history.push(previous);
    record.evidence.gates = record.evidence.gates.filter((item) => item.name !== name);
    record.evidence.gates.push(receipt);
    return receipt;
  }, cwd);
}

export function recordIntegrationReview(recordArg, { expectedRecordHash, reviewer, receipt } = {}, cwd = process.cwd()) {
  return withRecord(recordArg, expectedRecordHash, (record) => {
    assertExecutableM(record);
    validateGateReceipts(record);
    if (!/^[A-Za-z0-9][A-Za-z0-9._@-]{0,127}$/.test(reviewer || '') || reviewer === record.source.builder) fail('integration reviewer must be explicit and differ from the builder');
    const parsed = parseReviewReceipt(receipt, { expectedSnapshot: record.evidence.snapshot_hash });
    if (parsed.panel?.members.some((member) => member.reviewer === record.source.builder)) fail('review panel members must differ from the builder');
    const value = { ...parsed, reviewer, snapshot_hash: record.evidence.snapshot_hash, recorded_at: now() };
    value.identity = receiptIdentity(value);
    invalidateFinalization(record, 'integration review changed');
    if (record.evidence.review) record.evidence.review_history.push(record.evidence.review);
    record.evidence.review = value;
    return value;
  }, cwd);
}

export function recordIntegrationVerification(recordArg, { expectedRecordHash, verifier, results } = {}, cwd = process.cwd()) {
  return withRecord(recordArg, expectedRecordHash, (record) => {
    assertExecutableM(record);
    validateGateReceipts(record);
    const review = record.evidence.review || record.source.review;
    const reviewers = new Set([review.reviewer, ...(review.panel?.members || []).map((item) => item.reviewer)]);
    if (!/^[A-Za-z0-9][A-Za-z0-9._@-]{0,127}$/.test(verifier || '') || verifier === record.source.builder || reviewers.has(verifier)) {
      fail('integration verifier must differ from builder and every reviewer');
    }
    const criteria = parseVerificationResults(results, record.source.packet.acceptance);
    const value = { verifier, criteria, snapshot_hash: record.evidence.snapshot_hash, recorded_at: now() };
    value.identity = receiptIdentity(value);
    invalidateFinalization(record, 'integration verification changed');
    if (record.evidence.verification) record.evidence.verification_history.push(record.evidence.verification);
    record.evidence.verification = value;
    return value;
  }, cwd);
}

function effectiveEvidence(record) {
  if (!record.evidence.source_reusable && (!record.evidence.review || !record.evidence.verification)) {
    fail('changed integration inputs require fresh independent M review and verification');
  }
  const review = record.evidence.review || record.source.review;
  const verification = record.evidence.verification || record.source.verification;
  return { review, verification };
}

function validateGateReceipts(record) {
  for (const gate of [...record.evidence.gates, ...record.evidence.gate_history]) {
    if (!hasReceiptIdentity(gate)) fail('integration gate receipt identity is invalid');
    validateInternalLog(record, gate);
  }
}

function assertEvidenceReady(record, { finalized = false } = {}) {
  validateGateReceipts(record);
  for (const [name, command] of Object.entries(record.source.packet.commands)) {
    const gate = record.evidence.gates.find((item) => item.name === name && item.command === command);
    if (!gate || !hasReceiptIdentity(gate) || gate.status !== 'PASS' || gate.snapshot_hash !== record.evidence.snapshot_hash
      || gate.integration_commit !== record.integration.commit || gate.cwd !== '.'
      || gate.environment_additions_hash !== sha256(canonical({}))
      || gate.environment_hash !== environmentHandle(record.destination.root, gate.environment_additions_hash)) {
      fail(`fresh integration gate is missing or failed: ${name}`);
    }
  }
  const { review, verification } = effectiveEvidence(record);
  const reviewSnapshot = record.evidence.review ? record.evidence.snapshot_hash : record.source.snapshot_hash;
  const verificationSnapshot = record.evidence.verification ? record.evidence.snapshot_hash : record.source.snapshot_hash;
  if (!review || !hasReceiptIdentity(review) || review.status !== 'PASS'
    || review.snapshot_hash !== reviewSnapshot
    || review.findings.some((item) => !item.resolved && item.severity !== 'minor')) {
    fail('integration has unresolved review findings');
  }
  if (!verification || !hasReceiptIdentity(verification) || verification.snapshot_hash !== verificationSnapshot
    || verification.criteria.some((item) => item.status !== 'PASS')) {
    fail('integration acceptance verification is incomplete');
  }
  const reviewers = new Set([review.reviewer, ...(review.panel?.members || []).map((item) => item.reviewer)]);
  if (verification.verifier === record.source.builder || reviewers.has(verification.verifier)) {
    fail('integration verifier is not distinct from builder and reviewers');
  }
  if (finalized && (!record.evidence.finalized
    || record.evidence.effective_review_identity !== review.identity
    || record.evidence.effective_verification_identity !== verification.identity)) {
    fail('integration evidence finalization identity is missing or stale');
  }
  return { review, verification };
}

export function finalizeIntegrationEvidence(recordArg, { expectedRecordHash } = {}, cwd = process.cwd()) {
  return withRecord(recordArg, expectedRecordHash, (record) => {
    assertExecutableM(record);
    const { review, verification } = assertEvidenceReady(record);
    record.evidence.finalized = true;
    record.evidence.finalized_at = now();
    record.evidence.effective_review_identity = review.identity;
    record.evidence.effective_verification_identity = verification.identity;
    return { snapshot_hash: record.evidence.snapshot_hash, review: review.identity, verification: verification.identity };
  }, cwd);
}

function safeTrackedPath(rel) {
  if (typeof rel !== 'string' || path.isAbsolute(rel) || /[\x00-\x1f\x7f]/.test(rel)
    || rel.split('/').some((item) => !item || item === '.' || item === '..')
    || !/^(?:docs\/verification\/S\d+-\d+\.md|docs\/checklists\/verification-S\d+-\d+\.md|docs\/stories\/S\d+-\d+-[^/]+\.md|docs\/handoff\/[a-z0-9-]+\.md)$/.test(rel)) {
    fail(`unsafe integration artifact path: ${rel}`);
  }
  return rel;
}

function artifactFile(root, rel) {
  safeTrackedPath(rel);
  let cursor = root;
  for (const part of rel.split('/')) {
    cursor = path.join(cursor, part);
    try { if (fs.lstatSync(cursor).isSymbolicLink()) fail(`integration artifact path is a symlink: ${rel}`); }
    catch (error) { if (error.code !== 'ENOENT') throw error; }
  }
  return path.join(root, rel);
}

function readArtifact(root, rel) {
  const file = artifactFile(root, rel);
  try {
    const stat = fs.lstatSync(file);
    if (!stat.isFile() || stat.isSymbolicLink() || stat.size > 8 * 1024 * 1024) fail(`invalid integration artifact: ${rel}`);
    return fs.readFileSync(file, 'utf8');
  } catch (error) { if (error.code === 'ENOENT') return null; throw error; }
}

function writeArtifact(root, rel, content) {
  const file = artifactFile(root, rel);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  atomic(file, content);
}

function applyPending(root, pending) {
  for (const write of pending.writes) {
    const current = readArtifact(root, write.path);
    if (current !== write.before && current !== write.after) fail(`integration artifact changed concurrently: ${write.path}`);
  }
  for (const write of pending.writes) if (readArtifact(root, write.path) !== write.after) writeArtifact(root, write.path, write.after);
}

function handoffFinding(value) {
  return String(value).replace(/[\x00-\x1f\x7f]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 1000);
}

function openFindingLines(record) {
  const { review } = effectiveEvidence(record);
  const reviews = [{ label: 'source C', value: record.source.review }];
  if (review.identity !== record.source.review.identity) reviews.push({ label: 'effective M', value: review });
  const findings = reviews.flatMap(({ label, value }) => value.findings
    .filter((item) => !item.resolved).map((item) => ({ ...item, evidence_label: label, evidence_reviewer: value.reviewer })));
  if (!findings.length) return ['OPEN_FINDINGS: none'];
  return ['OPEN_FINDINGS:', ...findings.map((item) => `- [${item.severity}] ${item.evidence_label} · ${handoffFinding(item.lens || 'general')} / ${handoffFinding(item.reviewer || item.evidence_reviewer || 'unknown')}: ${handoffFinding(item.message)}`)];
}

function handoffContent(record, at, next) {
  return [
    `# HANDOFF ${at}`,
    '',
    `OBJECTIVE: ${record.source.story} completed`,
    `APPROVAL: approved · SCALE: ${record.plan.scale}`,
    `POSITION: story ${record.source.story} · status merged · rounds ${record.source.counters.fixes}/3 · retries ${record.source.counters.retries}/2 · verification: PASS`,
    '',
    `BASE_COMMIT: ${record.closure.commit}`,
    `BRANCH: ${record.destination.branch} · INTEGRATION: ${record.destination.branch} · UNCOMMITTED: none`,
    `READ_FIRST: ${record.source.story_path}, docs/plan.md`,
    'DONE_THIS_RUN:',
    `- Integrated candidate ${record.source.candidate} at M ${record.integration.commit}; closed at E ${record.closure.commit}.`,
    ...openFindingLines(record),
    'NEXT (ordered):',
    `1. ${next}`,
    '',
  ].join('\n');
}

function commitParents(root, commit) {
  return String(git(root, ['rev-list', '--parents', '-n', '1', commit])).trim().split(/\s+/).slice(1);
}

function commitEntry(root, commit, rel) {
  const raw = String(git(root, ['ls-tree', '-z', commit, '--', rel])).split('\0').filter(Boolean);
  if (raw.length !== 1) fail(`integration artifact is absent from commit: ${rel}`);
  const match = /^(\d{6}) (\w+) ([0-9a-f]+)\t(.+)$/.exec(raw[0]);
  if (!match || match[2] !== 'blob' || match[4] !== rel) fail(`integration artifact commit entry is invalid: ${rel}`);
  return { mode: match[1], oid: match[3] };
}

function committedText(root, commit, rel) {
  try { return git(root, ['show', `${commit}:${rel}`], { buffer: true }).toString('utf8'); }
  catch { return null; }
}

function validateAdoptedArtifact(record, field) {
  const stage = record[field];
  if (!OID.test(stage.commit || '') || !stage.proof || stage.pending !== null
    || stage.proof.commit !== stage.commit || tree(record.destination.root, stage.commit) !== stage.proof.tree
    || canonical(commitParents(record.destination.root, stage.commit)) !== canonical([stage.proof.parent])) {
    fail(`${field} adopted commit proof is invalid`);
  }
  validateArtifactPending(record, field, stage.proof);
  const changed = String(git(record.destination.root, ['diff-tree', '--no-commit-id', '--name-only', '-r', stage.proof.parent, stage.commit, '--']))
    .trim().split(/\r?\n/).filter(Boolean).sort();
  const paths = stage.proof.writes.map((item) => item.path).sort();
  if (canonical(changed) !== canonical(paths)) fail(`${field} adopted commit changes unprepared paths`);
  for (const write of stage.proof.writes) {
    const entry = commitEntry(record.destination.root, stage.commit, write.path);
    if (entry.mode !== write.mode || entry.oid !== write.oid || committedText(record.destination.root, stage.commit, write.path) !== write.after
      || committedText(record.destination.root, stage.proof.parent, write.path) !== write.before) {
      fail(`${field} adopted bytes, mode or parent image changed`);
    }
  }
}

function validateIntegrationProofs(record) {
  const root = rootPath(record.destination.root);
  if (commonRepository(root) !== record.destination.common_repository) fail('integration repository identity changed');
  if (record.integration.base_anchor?.head !== record.integration.base
    || record.integration.base_anchor?.tree !== tree(root, record.integration.base)
    || record.integration.base_anchor?.ref !== `refs/heads/${record.destination.branch}`) {
    fail('integration base I identity is invalid');
  }
  validateCheckoutProofObjects(root, record.integration.base, record.integration.base_checkout_proof);
  const mismatches = [...new Set([
    ...manifestMismatches(record.source.manifest, record.source.snapshot_manifest),
    ...(record.integration.manifest ? manifestMismatches(record.source.manifest, record.integration.manifest) : []),
  ])].sort();
  const reusable = record.integration.manifest !== null && mismatches.length === 0;
  if (record.evidence.source_reusable !== reusable || canonical(record.evidence.reuse_mismatches) !== canonical(mismatches)
    || (record.integration.manifest && canonical(record.manifest) !== canonical(record.integration.manifest))) {
    fail('integration evidence reusability or manifest binding is invalid');
  }
  if (record.integration.status === 'prepared') {
    if (expectedMergeTree(root, record.integration.base, record.source.candidate) !== record.integration.expected_tree) {
      fail('prepared integration composition changed');
    }
    validateCheckoutProofObjects(root, record.integration.expected_tree, record.integration.checkout_proof);
  } else if (record.integration.status === 'failed') {
    if (record.integration.failure.integration !== record.integration.base
      || record.integration.failure.candidate !== record.source.candidate
      || canonical(record.integration.failure.argv) !== canonical(['git', '-C', root, 'merge-tree', '--write-tree', record.integration.base, record.source.candidate])
      || typeof record.integration.failure.git_version !== 'string' || !record.integration.failure.git_version.startsWith('git version ')
      || (record.integration.failure.status !== null && !Number.isInteger(record.integration.failure.status))
      || record.integration.failure.status === 0
      || (record.integration.failure.status === null && typeof record.integration.failure.error !== 'string')
      || !HASH.test(record.integration.failure.stdout_hash || '') || !HASH.test(record.integration.failure.stderr_hash || '')
      || Number.isNaN(Date.parse(record.integration.failure.started_at)) || Number.isNaN(Date.parse(record.integration.failure.finished_at))) {
      fail('failed merge probe is not bound to its actual I/C attempt');
    }
  } else if (record.integration.status === 'adopted') {
    const parents = commitParents(root, record.integration.commit);
    if (canonical(parents) !== canonical([record.integration.base, record.source.candidate])
      || tree(root, record.integration.commit) !== record.integration.tree
      || record.integration.tree !== record.integration.expected_tree
      || expectedMergeTree(root, record.integration.base, record.source.candidate) !== record.integration.expected_tree) {
      fail('adopted integration M topology changed');
    }
    validateCheckoutProofObjects(root, record.integration.commit, record.integration.checkout_proof);
    const manifest = boundManifest(root, record.integration.commit, record.source.packet, record.source.story_path,
      record.integration.manifest.bindings);
    if (canonical(manifest) !== canonical(record.integration.manifest)
      || integrationIdentity(record) !== record.evidence.snapshot_hash) fail('adopted integration M manifest changed');
  }
  for (const field of ['report', 'closure', 'handoff']) {
    if (record[field].commit !== null) validateAdoptedArtifact(record, field);
    else if (record[field].proof !== null) fail(`${field} proof exists without an adopted commit`);
    if (record[field].pending !== null) validateArtifactPending(record, field, record[field].pending);
  }
  if (record.report.commit && record.reporting === 'skipped') fail('report P exists for a skipped reporting contract');
  if (record.closure.commit && record.reporting !== 'skipped' && !record.report.commit) fail('closure E bypasses required report P');
  if (record.handoff.commit && !record.closure.commit) fail('handoff H exists without closure E');
}

function validateArtifactPending(record, field, pending) {
  if (!pending || !OID.test(pending.parent) || !Array.isArray(pending.writes) || !pending.writes.length
    || !pending.writes.every((write) => typeof write.path === 'string' && (write.before === null || typeof write.before === 'string')
      && typeof write.after === 'string' && write.hash === sha256(write.after))) fail(`invalid ${field} preparation`);
  if (field === 'report') {
    const { review, verification } = assertEvidenceReady(record, { finalized: true });
    const story = parseStory(String(git(record.destination.root, ['show', `${pending.parent}:${record.source.story_path}`])), record.source.story_path);
    const artifacts = renderVerificationArtifacts(record, story, review, verification);
    const expected = {
      [`docs/verification/${record.source.story}.md`]: artifacts.report,
      [`docs/checklists/verification-${record.source.story}.md`]: artifacts.checklist,
    };
    if (pending.parent !== record.integration.commit || pending.writes.length !== 2
      || pending.writes.some((write) => write.before !== null || expected[write.path] !== write.after)) fail('report preparation no longer matches finalized evidence');
  } else if (field === 'closure') {
    if (pending.writes.length !== 1 || pending.writes[0].path !== record.source.story_path
      || typeof pending.writes[0].before !== 'string') fail('closure preparation must contain only the existing bound story');
    const expectedParent = record.report.commit || record.integration.commit;
    if (pending.parent !== expectedParent || (record.reporting !== 'skipped' && !record.report.commit)) {
      fail('closure preparation does not follow the required evidence commit');
    }
    assertEvidenceReady(record, { finalized: true });
    const before = parseStory(pending.writes[0].before, record.source.story_path);
    const after = parseStory(pending.writes[0].after, record.source.story_path);
    if (before.contractHash !== record.source.contract_hash || before.executionHash !== record.source.execution_hash
      || after.execution?.status !== 'merged' || typeof after.execution.updated !== 'string') fail('closure preparation changed the story contract or source execution');
    const generated = replaceStoryExecution(before, { status: 'merged', updated: after.execution.updated }, {
      note: `${after.execution.updated} integrated at ${record.integration.commit}`,
    });
    if (generated.after !== pending.writes[0].after || generated.executionHash !== record.closure.execution_hash) fail('closure preparation is not the exact legal Execution transition');
  } else if (field === 'handoff') {
    assertEvidenceReady(record, { finalized: true });
    if (pending.parent !== record.closure.commit || pending.writes.length !== 1 || pending.writes[0].path !== record.handoff.path
      || pending.writes[0].after !== handoffContent(record, pending.handoff_at, pending.next)) fail('handoff preparation no longer matches closure E');
  }
}

function prepareArtifacts(recordArg, expectedRecordHash, field, build, cwd) {
  const updated = withRecord(recordArg, expectedRecordHash, (record) => {
    const root = destinationRoot(record);
    if (record[field].commit) fail(`${field} commit is already adopted`);
    if (record[field].pending) {
      if (head(root) !== record[field].pending.parent) fail(`${field} pending parent is no longer current`);
      validateArtifactPending(record, field, record[field].pending);
      const allowed = new Set(record[field].pending.writes.map((item) => item.path));
      const extra = statusPaths(root).filter((rel) => !allowed.has(rel));
      if (extra.length) fail(`${field} recovery found unrelated worktree changes: ${extra.sort().join(', ')}`);
      applyPending(root, record[field].pending);
      return record[field].pending;
    }
    assertClean(root);
    const pending = build(record, root);
    pending.token = randomUUID();
    pending.prepared_at = now();
    for (const write of pending.writes) {
      write.path = safeTrackedPath(write.path);
      write.before = readArtifact(root, write.path);
      if (typeof write.after !== 'string' || Buffer.byteLength(write.after) > 8 * 1024 * 1024) fail('integration artifact bytes are invalid');
      write.hash = sha256(write.after);
    }
    record[field].pending = pending;
    return pending;
  }, cwd);
  applyPending(updated.record.destination.root, updated.result);
  return updated;
}

function adoptArtifacts(recordArg, { expectedRecordHash, token, commit } = {}, field, cwd) {
  return withRecord(recordArg, expectedRecordHash, (record) => {
    const pending = record[field].pending;
    if (!pending || pending.token !== token || !OID.test(commit || '')) fail(`${field} adoption token or commit is invalid`);
    validateArtifactPending(record, field, pending);
    const root = rootPath(record.destination.root);
    if (head(root) !== commit || branch(root) !== record.destination.branch) fail(`${field} commit is not current integration HEAD`);
    assertClean(root);
    const parents = String(git(root, ['rev-list', '--parents', '-n', '1', commit])).trim().split(/\s+/);
    if (parents.length !== 2 || parents[1] !== pending.parent) fail(`${field} commit must be a direct child of its prepared parent`);
    const changed = String(git(root, ['diff-tree', '--no-commit-id', '--name-only', '-r', pending.parent, commit, '--'])).trim().split(/\r?\n/).filter(Boolean).sort();
    const paths = pending.writes.map((item) => item.path).sort();
    if (canonical(changed) !== canonical(paths)) fail(`${field} commit changes paths outside its prepared artifact set`);
    for (const write of pending.writes) {
      const bytes = git(root, ['show', `${commit}:${write.path}`], { buffer: true });
      if (sha256(bytes) !== write.hash || fs.readFileSync(artifactFile(root, write.path), 'utf8') !== write.after) fail(`${field} committed bytes differ from preparation`);
      const entry = commitEntry(root, commit, write.path);
      write.mode = entry.mode;
      write.oid = entry.oid;
    }
    record[field].commit = commit;
    record[field].proof = { ...structuredClone(pending), commit, tree: tree(root, commit) };
    record[field].pending = null;
    record[field].adopted_at = now();
    return { commit, paths };
  }, cwd);
}

export function prepareVerificationReport(recordArg, { expectedRecordHash } = {}, cwd = process.cwd()) {
  return prepareArtifacts(recordArg, expectedRecordHash, 'report', (record, root) => {
    if (record.reporting === 'skipped') fail('this integration does not require or request a verification report');
    assertExecutableM(record);
    const { review, verification } = assertEvidenceReady(record, { finalized: true });
    if (head(root) !== record.integration.commit) fail('verification report P must begin at M');
    const story = readStory(root, record.source.story_path);
    const artifacts = renderVerificationArtifacts(record, story, review, verification);
    const reportPath = `docs/verification/${record.source.story}.md`;
    const checklistPath = `docs/checklists/verification-${record.source.story}.md`;
    if (readArtifact(root, reportPath) !== null || readArtifact(root, checklistPath) !== null) fail('verification reporting paths must be new at P');
    return { parent: record.integration.commit, writes: [
      { path: reportPath, after: artifacts.report },
      { path: checklistPath, after: artifacts.checklist },
    ] };
  }, cwd);
}

export function adoptVerificationReport(recordArg, options = {}, cwd = process.cwd()) {
  return adoptArtifacts(recordArg, options, 'report', cwd);
}

export function prepareStoryClosure(recordArg, { expectedRecordHash } = {}, cwd = process.cwd()) {
  return prepareArtifacts(recordArg, expectedRecordHash, 'closure', (record, root) => {
    assertEvidenceReady(record, { finalized: true });
    if (record.reporting !== 'skipped' && !record.report.commit) fail('required or requested verification report P is missing');
    const parent = record.report.commit || record.integration.commit;
    if (head(root) !== parent) fail('story closure E must begin at the final evidence commit');
    const story = readStory(root, record.source.story_path);
    if (story.contractHash !== record.source.contract_hash || story.executionHash !== record.source.execution_hash
      || story.execution?.status !== 'in-review') fail('story at integration does not match finished candidate C');
    const closedAt = stamp();
    const closed = replaceStoryExecution(story, { status: 'merged', updated: closedAt }, {
      note: `${closedAt} integrated at ${record.integration.commit}`,
    });
    record.closure.execution_hash = closed.executionHash;
    return { parent, writes: [{ path: record.source.story_path, after: closed.after }] };
  }, cwd);
}

export function adoptStoryClosure(recordArg, options = {}, cwd = process.cwd()) {
  return adoptArtifacts(recordArg, options, 'closure', cwd);
}

export function prepareIntegrationHandoff(recordArg, { expectedRecordHash, next = 'Continue with the next ready story.' } = {}, cwd = process.cwd()) {
  if (typeof next !== 'string' || !next.trim() || next.length > 1000 || /[\x00-\x1f\x7f]/.test(next)) fail('handoff next action is invalid');
  return prepareArtifacts(recordArg, expectedRecordHash, 'handoff', (record, root) => {
    assertEvidenceReady(record, { finalized: true });
    if (!record.closure.commit || head(root) !== record.closure.commit) fail('handoff H must begin at closure E');
    const handoffAt = stamp();
    return {
      parent: record.closure.commit, handoff_at: handoffAt, next,
      writes: [{ path: record.handoff.path, after: handoffContent(record, handoffAt, next) }],
    };
  }, cwd);
}

export function adoptIntegrationHandoff(recordArg, options = {}, cwd = process.cwd()) {
  return adoptArtifacts(recordArg, options, 'handoff', cwd);
}

import { canonical, DeliverError, readJsonFile, sha256 } from './state.mjs';
import { assertPanelCoverage } from './review.mjs';

const fail = (message) => { throw new DeliverError(message, 66); };

export function parseVerificationResults(input, acceptance) {
  const document = typeof input === 'string' ? readJsonFile(input, 'verification results') : input;
  if (!document || typeof document !== 'object' || Array.isArray(document) || !Array.isArray(document.criteria)) {
    fail('verification results must contain a criteria array');
  }
  const criteria = document.criteria.map((criterion, index) => {
    if (!criterion || typeof criterion !== 'object' || Array.isArray(criterion) || typeof criterion.id !== 'string'
      || !['PASS', 'FAIL', 'UNKNOWN'].includes(criterion.status) || typeof criterion.evidence !== 'string'
      || !criterion.evidence.trim() || criterion.evidence.length > 8000) fail(`invalid verification criterion at index ${index}`);
    return { id: criterion.id, status: criterion.status, evidence: criterion.evidence };
  });
  const expected = acceptance.map((item) => item.id).sort();
  const actual = criteria.map((item) => item.id).sort();
  if (new Set(actual).size !== actual.length || canonical(actual) !== canonical(expected)) {
    fail('verification criteria must cover each acceptance id exactly once');
  }
  return criteria;
}

function cleanCell(value) {
  return String(value).replace(/[\x00-\x1f\x7f]+/g, ' ').replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;').replace(/\|/g, '&#124;').replace(/`/g, '&#96;').replace(/\[/g, '&#91;').replace(/\]/g, '&#93;');
}

function findingRows(label, evidence) {
  const findings = evidence?.findings || [];
  if (!findings.length) return [`| ${label} | none | none | none | none |`];
  return findings.map((item) => `| ${label} | ${cleanCell(item.lens || 'general')} | ${cleanCell(item.reviewer || evidence.reviewer || 'unknown')} | ${item.severity} / ${item.resolved ? 'resolved' : 'open'} | ${cleanCell(item.message)} |`);
}

export function renderVerificationArtifacts(record, story, review, verification) {
  if (!record?.evidence?.finalized || !record.integration?.commit) fail('integration evidence must be finalized before reporting');
  if (verification.criteria.some((item) => item.status !== 'PASS')) fail('verification report cannot claim unsupported PASS criteria');
  const requiredLenses = assertPanelCoverage(review, story, record.plan.scale);
  const source = record.source;
  const sourceReview = source.review || review;
  const lines = [
    `# Verification: ${source.story}`,
    '',
    `- Story: ${source.story_path}`,
    `- Candidate C: ${source.candidate}`,
    `- Source snapshot: ${source.snapshot_hash}`,
    `- Integrated M: ${record.integration.commit}`,
    `- Manifest: ${record.manifest.hash}`,
    `- Gate receipts: ${record.evidence.gates.map((item) => item.identity).join(', ') || 'none declared'}`,
    `- Review receipt: ${review.identity}`,
    `- Verification receipt: ${verification.identity}`,
    '',
    '## Gates',
    '',
    '| Gate | Command | Result |',
    '| --- | --- | --- |',
    ...record.evidence.gates.map((gate) => `| ${cleanCell(gate.name)} | ${cleanCell(gate.command)} | ${gate.status} |`),
    ...(record.evidence.gates.length ? [] : ['| none declared | N/A | PASS |']),
    '',
    '## Review panel',
    '',
    '| Lens | Reviewer | Verdict |',
    '| --- | --- | --- |',
    ...review.panel.members.map((member) => `| ${member.lens} | ${cleanCell(member.reviewer)} | ${member.verdict} |`),
    '',
    '## Retained findings',
    '',
    '| Evidence | Lens | Reviewer | Status | Finding |',
    '| --- | --- | --- | --- | --- |',
    ...findingRows('Source C', sourceReview),
    ...(review.identity === sourceReview.identity ? [] : findingRows('Effective M', review)),
    '',
    '## Acceptance verification',
    '',
    '| Criterion | Result | Evidence |',
    '| --- | --- | --- |',
    ...verification.criteria.map((item) => `| ${cleanCell(item.id)} | ${item.status} | ${cleanCell(item.evidence)} |`),
    '',
    '## Integration status',
    '',
    `Integrated at M ${record.integration.commit}. This report does not identify its own commit.`,
    '',
  ];
  const checklist = [
    `# Verification checklist: ${source.story}`,
    '',
    `Candidate C: ${source.candidate}`,
    `Integrated M: ${record.integration.commit}`,
    '',
    ...verification.criteria.map((item) => `- [x] ${cleanCell(item.id)}: ${item.status}. Evidence: ${cleanCell(item.evidence)}`),
    ...requiredLenses.map((lens) => {
      const member = review.panel.members.find((item) => item.lens === lens);
      return `- [x] Review lens ${lens}: ${member.verdict}. Evidence: reviewer ${member.reviewer}, snapshot ${member.snapshot_hash}.`;
    }),
    '',
  ];
  const report = `${lines.join('\n')}\n`;
  const checklistText = `${checklist.join('\n')}\n`;
  return {
    report,
    checklist: checklistText,
    report_hash: sha256(report),
    checklist_hash: sha256(checklistText),
  };
}

import { DeliverError, readJsonFile } from './state.mjs';

const record = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const identity = (value) => typeof value === 'string' && /^[A-Za-z0-9][A-Za-z0-9._@-]{0,127}$/.test(value);
const digest = (value) => typeof value === 'string' && /^[0-9a-f]{64}$/.test(value);
const fail = (message) => { throw new DeliverError(message, 66); };

function finding(value, label) {
  if (!record(value) || !['block', 'major', 'minor'].includes(value.severity)
    || typeof value.message !== 'string' || !value.message.trim() || value.message.length > 4000
    || (value.path !== undefined && (typeof value.path !== 'string' || value.path.length > 1000))
    || (value.resolved !== undefined && typeof value.resolved !== 'boolean')) fail(`invalid review finding in ${label}`);
  return {
    severity: value.severity,
    message: value.message,
    ...(value.path === undefined ? {} : { path: value.path }),
    resolved: value.resolved === true,
  };
}

export function parseReviewReceipt(input, { expectedSnapshot } = {}) {
  const receipt = typeof input === 'string' ? readJsonFile(input, 'review receipt') : input;
  if (!record(receipt) || !['PASS', 'FAIL'].includes(receipt.status) || !Array.isArray(receipt.findings)) {
    fail('review receipt must contain status PASS|FAIL and a findings array');
  }
  const topFindings = receipt.findings.map((item, index) => finding(item, `top-level findings[${index}]`));
  if (receipt.summary !== undefined && (typeof receipt.summary !== 'string' || receipt.summary.length > 8000)) fail('review summary must be a bounded string');
  if (receipt.panel === undefined) {
    if (receipt.status === 'PASS' && topFindings.some((item) => !item.resolved && item.severity !== 'minor')) {
      fail('a PASS review may not contain unresolved block or major findings');
    }
    return { status: receipt.status, findings: topFindings, ...(receipt.summary === undefined ? {} : { summary: receipt.summary }) };
  }
  const panel = receipt.panel;
  if (!record(panel) || !digest(panel.snapshot_hash) || !Array.isArray(panel.members) || !panel.members.length || panel.members.length > 16) {
    fail('review panel must bind one to sixteen members to a snapshot');
  }
  if (expectedSnapshot !== undefined && panel.snapshot_hash !== expectedSnapshot) fail('review panel snapshot does not match the reviewed snapshot');
  const members = panel.members.map((member, index) => {
    if (!record(member) || typeof member.lens !== 'string' || !/^[a-z][a-z0-9-]{0,63}$/.test(member.lens)
      || !identity(member.reviewer) || !['PASS', 'CONCERNS', 'FAIL'].includes(member.verdict)
      || member.snapshot_hash !== panel.snapshot_hash || !Array.isArray(member.findings)) fail(`invalid review panel member at index ${index}`);
    const findings = member.findings.map((item, findingIndex) => finding(item, `panel member ${index} finding ${findingIndex}`));
    if (member.verdict === 'PASS' && findings.some((item) => !item.resolved && item.severity !== 'minor')) fail('PASS panel member has unresolved blocking findings');
    if (member.verdict === 'CONCERNS' && !findings.some((item) => !item.resolved)) fail('CONCERNS panel member must retain an unresolved finding');
    return { lens: member.lens, reviewer: member.reviewer, verdict: member.verdict, snapshot_hash: member.snapshot_hash, findings };
  });
  if (new Set(members.map((item) => item.lens)).size !== members.length) fail('review panel lenses must be unique');
  const findings = members.flatMap((member) => member.findings.map((item) => ({ ...item, lens: member.lens, reviewer: member.reviewer })));
  const status = members.some((member) => member.verdict === 'FAIL')
    || findings.some((item) => !item.resolved && item.severity !== 'minor') ? 'FAIL' : 'PASS';
  if (receipt.status !== status) fail('review status must equal the verdict derived from panel members');
  return {
    status,
    findings,
    ...(receipt.summary === undefined ? {} : { summary: receipt.summary }),
    panel: { snapshot_hash: panel.snapshot_hash, members },
  };
}

export function requiredReviewLenses(story, scale) {
  const required = new Set(['code-integrity-reviewer', ...(story.reviewLenses || [])]);
  if (scale === 'regulated') required.add('security-auditor');
  return [...required].sort();
}

export function assertPanelCoverage(review, story, scale) {
  const required = requiredReviewLenses(story, scale);
  if (!review?.panel) fail(`durable reporting requires a structured review panel covering: ${required.join(', ')}`);
  const actual = new Set(review.panel.members.map((item) => item.lens));
  const missing = required.filter((lens) => !actual.has(lens));
  if (missing.length) fail(`review panel is missing required lenses: ${missing.join(', ')}`);
  return required;
}

import fs from 'node:fs';
import path from 'node:path';
import { createHash, randomUUID } from 'node:crypto';

export const STATE_VERSION = 1;

export class DeliverError extends Error {
  constructor(message, code = 70, details = undefined) {
    super(message);
    this.name = 'DeliverError';
    this.code = code;
    this.details = details;
  }
}

export const sha256 = (value) => createHash('sha256').update(value).digest('hex');

export function canonical(value) {
  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonical(value[key])}`).join(',')}}`;
  }
  return JSON.stringify(value);
}

export function readJsonFile(file, label = file) {
  let raw;
  try {
    if (fs.statSync(file).size > 8 * 1024 * 1024) throw new Error('file exceeds 8 MiB');
    raw = fs.readFileSync(file, 'utf8');
  }
  catch (error) { throw new DeliverError(`cannot read ${label}: ${error.message}`, 66); }
  try { return JSON.parse(raw); }
  catch (error) { throw new DeliverError(`invalid JSON in ${label}: ${error.message}`, 66); }
}

const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const isStringArray = (value) => Array.isArray(value) && value.every((item) => typeof item === 'string');
const safeBranch = (value) => typeof value === 'string' && value && value.length <= 512 && value !== '@'
  && !value.startsWith('-') && !value.startsWith('/') && !value.endsWith('/') && !value.endsWith('.')
  && !value.includes('..') && !value.includes('//') && !value.includes('@{')
  && !/[\x00-\x20\x7f~^:?*[\\\]]/.test(value)
  && value.split('/').every((part) => part && !part.startsWith('.') && !part.endsWith('.lock'));
const safeRef = (value) => typeof value === 'string' && value.startsWith('refs/heads/') && safeBranch(value.slice('refs/heads/'.length));
const safeRelativePath = (value) => typeof value === 'string' && value && !path.isAbsolute(value)
  && !/[\x00-\x1f\x7f]/.test(value) && !value.split(/[\\/]/).some((part) => !part || part === '.' || part === '..')
  && !/^(?:\.git|\.deliver)(?:[\\/]|$)/.test(value);
const oid = (value) => typeof value === 'string' && /^[0-9a-f]{40}(?:[0-9a-f]{24})?$/.test(value);
const digest = (value) => typeof value === 'string' && /^[0-9a-f]{64}$/.test(value);

function validNestedAnchor(anchor) {
  if (!isObject(anchor) || !['head', 'tree', 'index_tree', 'index_flags', 'protected_hash']
    .every((key) => typeof anchor[key] === 'string')
    || !oid(anchor.head) || !oid(anchor.tree) || !oid(anchor.index_tree)
    || !digest(anchor.index_flags) || !digest(anchor.protected_hash)
    || (anchor.metadata_version !== undefined && anchor.metadata_version !== 'protected-v2')) return false;
  if (anchor.submodules === undefined) return true;
  return isObject(anchor.submodules) && Object.entries(anchor.submodules)
    .every(([rel, nested]) => safeRelativePath(rel) && validNestedAnchor(nested));
}

export function archiveEvidence(state, reason, details = {}, archivedAt = new Date().toISOString()) {
  if (!isObject(state) || typeof reason !== 'string' || !reason.trim() || !isObject(details)
    || typeof archivedAt !== 'string' || Number.isNaN(Date.parse(archivedAt))) {
    throw new DeliverError('cannot archive evidence without a state, reason and detail object', 66);
  }
  const hasEvidence = state.gates.length > 0 || state.review !== null || state.verification !== null;
  if (hasEvidence) {
    if (state.evidence_history === undefined) state.evidence_history = [];
    state.evidence_history.push({
      at: archivedAt,
      reason,
      details: structuredClone(details),
      gates: structuredClone(state.gates),
      review: structuredClone(state.review),
      verification: structuredClone(state.verification),
    });
  }
  state.gates = [];
  state.review = null;
  state.verification = null;
}

export function validateTaskPacket(packet) {
  if (!isObject(packet)) throw new DeliverError('task packet must be a JSON object', 66);
  const unknown = Object.keys(packet).filter((key) => !['id', 'objective', 'acceptance', 'read_paths', 'touches', 'commands', 'specs'].includes(key));
  if (unknown.length) throw new DeliverError(`unsupported task fields: ${unknown.join(', ')}`, 66);
  for (const key of ['id', 'objective']) {
    if (typeof packet[key] !== 'string' || packet[key].trim() === '') throw new DeliverError(`task packet ${key} must be a non-empty string`, 66);
  }
  if (!Array.isArray(packet.acceptance) || packet.acceptance.length === 0) {
    throw new DeliverError('task packet acceptance must be a non-empty array', 66);
  }
  const acceptance = packet.acceptance.map((item, index) => {
    if (!isObject(item) || typeof item.id !== 'string' || item.id.trim() === '' || typeof item.text !== 'string' || item.text.trim() === '') {
      throw new DeliverError(`task packet acceptance[${index}] must contain non-empty id and text strings`, 66);
    }
    return { id: item.id, text: item.text };
  });
  if (new Set(acceptance.map((item) => item.id)).size !== acceptance.length) throw new DeliverError('task packet acceptance ids must be unique', 66);
  if (!isStringArray(packet.read_paths) || !isStringArray(packet.touches)) {
    throw new DeliverError('task packet read_paths and touches must be string arrays', 66);
  }
  if (packet.touches.length === 0) throw new DeliverError('task packet touches must not be empty', 66);
  if (!isObject(packet.commands)) throw new DeliverError('task packet commands must be an object; use {} to record N/A', 66);
  const commands = Object.create(null);
  for (const [name, command] of Object.entries(packet.commands)) {
    if (!/^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/.test(name) || typeof command !== 'string' || command.trim() === '') {
      throw new DeliverError('task packet command names and values must be non-empty safe strings', 66);
    }
    commands[name] = command;
  }
  if (packet.specs !== undefined && !isStringArray(packet.specs)) throw new DeliverError('task packet specs must be an array of strings', 66);
  return {
    id: packet.id,
    objective: packet.objective,
    acceptance,
    read_paths: [...packet.read_paths],
    touches: [...packet.touches],
    commands,
    specs: [...(packet.specs || [])],
  };
}

export function validateRunState(state) {
  const fail = (message) => { throw new DeliverError(`invalid run state: ${message}`, 66); };
  if (!isObject(state)) fail('root must be an object');
  if (state.schema_version !== STATE_VERSION) fail(`schema_version must be ${STATE_VERSION}`);
  if (typeof state.run_id !== 'string' || !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(state.run_id)) fail('bad run_id');
  if (!['quick', 'managed', 'governed'].includes(state.mode)) fail('bad mode');
  if (!Number.isSafeInteger(state.revision) || state.revision < 0) fail('bad revision');
  if (typeof state.project_root !== 'string' || !path.isAbsolute(state.project_root)) fail('bad project_root');
  if (!isObject(state.plan) || (state.plan.path !== null && typeof state.plan.path !== 'string') || typeof state.plan.hash !== 'string') fail('bad plan');
  if (state.approval !== null && (!isObject(state.approval) || typeof state.approval.approver !== 'string' || typeof state.approval.plan_hash !== 'string')) fail('bad approval');
  if (!['initialized', 'starting', 'active', 'finished'].includes(state.phase)) fail('bad phase');
  if (!isObject(state.counters) || !['retries', 'fixes', 'corrections'].every((key) => Number.isSafeInteger(state.counters[key]) && state.counters[key] >= 0)) fail('bad counters');
  if (!Array.isArray(state.events) || !Array.isArray(state.gates) || !Array.isArray(state.checkpoints)) fail('bad collections');
  if (state.task !== null) {
    if (!isObject(state.task) || typeof state.task.builder !== 'string' || !isObject(state.task.packet)) fail('bad task');
    validateTaskPacket(state.task.packet);
  }
  if (state.baseline !== null) {
    if (!isObject(state.baseline) || !isObject(state.baseline.snapshot) || !isObject(state.baseline.snapshot.entries)
      || typeof state.baseline.snapshot.git_meta !== 'string' || typeof state.baseline.snapshot.hash !== 'string'
      || !isStringArray(state.baseline.dirty_paths)) fail('bad baseline');
    const expectedHash = sha256(canonical({ entries: state.baseline.snapshot.entries, git_meta: state.baseline.snapshot.git_meta }));
    if (state.baseline.snapshot.hash !== expectedHash) fail('baseline snapshot hash does not match its content');
  }
  if (state.pm_binding !== undefined && state.pm_binding !== null) {
    const binding = state.pm_binding;
    const safeActor = (value) => typeof value === 'string' && /^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?-[a-f0-9]{12}$/.test(value);
    const safeStoryPath = (value) => typeof value === 'string' && /^docs\/stories\/S\d+-\d+-[^/\\]+\.md$/.test(value);
    if (!isObject(binding)) fail('bad PM binding');
    if (binding.format === 'current') {
      if (!['actor', 'story', 'story_path', 'contract_hash', 'execution_hash', 'plan_digest', 'branch', 'builder', 'integration_branch']
        .every((key) => typeof binding[key] === 'string')) fail('bad current PM binding');
      if (!safeActor(binding.actor) || !/^S\d+-\d+$/.test(binding.story) || !safeStoryPath(binding.story_path)
        || !/^[0-9a-f]{64}$/.test(binding.contract_hash) || !/^[0-9a-f]{64}$/.test(binding.execution_hash)
        || !/^[0-9a-f]{40}(?:[0-9a-f]{24})?$/.test(binding.plan_digest)
        || !safeBranch(binding.branch) || !safeBranch(binding.integration_branch)
        || !['codex-builder', 'expert-builder'].includes(binding.builder)) fail('unsafe current PM binding');
    } else {
      if (binding.format !== undefined && binding.format !== 'legacy') fail('unsupported PM binding format');
      if (!['actor', 'story', 'story_path', 'story_hash', 'integration_branch', 'actor_path'].every((key) => typeof binding[key] === 'string')) fail('bad legacy PM binding');
      if (!safeActor(binding.actor) || binding.actor_path !== `pm/actors/${binding.actor}.json`
        || !binding.story_path.startsWith('docs/stories/') || binding.story_path.split(/[\\/]/).includes('..')) fail('unsafe legacy PM binding');
    }
  }
  if (state.git_anchor !== undefined && state.git_anchor !== null) {
    const anchor = state.git_anchor;
    if (!isObject(anchor) || !['head', 'ref', 'tree', 'index_tree', 'index_flags', 'protected_hash']
      .every((key) => typeof anchor[key] === 'string')) fail('bad git anchor');
    if (!oid(anchor.head) || !oid(anchor.tree) || !oid(anchor.index_tree)
      || !digest(anchor.index_flags) || !digest(anchor.protected_hash)
      || !safeRef(anchor.ref)
      || (anchor.metadata_version !== undefined && anchor.metadata_version !== 'protected-v2')
      || (anchor.submodules !== undefined && (!isObject(anchor.submodules) || !Object.entries(anchor.submodules)
        .every(([rel, nested]) => safeRelativePath(rel) && validNestedAnchor(nested))))) fail('unsafe git anchor');
  }
  if (state.baseline_metadata_version !== undefined
    && (state.baseline_metadata_version !== 'legacy-v1' || !state.git_anchor)) fail('bad baseline metadata compatibility marker');
  if (state.execution_audit !== undefined && state.execution_audit !== null) {
    const audit = state.execution_audit;
    if (!isObject(audit) || typeof audit.story_path !== 'string' || typeof audit.contract_hash !== 'string'
      || !(audit.original_entry === null || /^file:(?:644|755):[0-9a-f]{64}$/.test(audit.original_entry))
      || !/^file:(?:644|755):[0-9a-f]{64}$/.test(audit.current_entry) || !Array.isArray(audit.transitions)
      || !/^docs\/stories\/S\d+-\d+-[^/\\]+\.md$/.test(audit.story_path)
      || !/^[0-9a-f]{64}$/.test(audit.contract_hash)) fail('bad Execution audit');
    for (const item of audit.transitions) {
      if (!isObject(item) || !['from', 'to', 'before_hash', 'after_hash', 'at'].every((key) => typeof item[key] === 'string')
        || !['claimed', 'building', 'built', 'in-review', 'blocked'].includes(item.from)
        || !['claimed', 'building', 'built', 'in-review', 'blocked'].includes(item.to)
        || !/^[0-9a-f]{64}$/.test(item.before_hash) || !/^[0-9a-f]{64}$/.test(item.after_hash)
        || !(item.reason === null || typeof item.reason === 'string')
        || (item.attempt !== null && item.attempt !== undefined && !['fix', 'retry'].includes(item.attempt))) fail('bad Execution transition receipt');
    }
  }
  if (state.commit_adoption !== undefined && state.commit_adoption !== null) {
    const adoption = state.commit_adoption;
    if (!isObject(adoption) || !Array.isArray(adoption.history) || !(adoption.pending === null || isObject(adoption.pending))) fail('bad commit adoption state');
    if (adoption.pending) {
      const pending = adoption.pending;
      if (!['token', 'parent', 'ref', 'expected_tree', 'expected_index_flags', 'content_hash', 'protected_hash', 'prepared_at'].every((key) => typeof pending[key] === 'string')
        || !Array.isArray(pending.paths) || !isStringArray(pending.paths) || !pending.paths.every(safeRelativePath)
        || !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(pending.token)
        || ![pending.parent, pending.expected_tree].every((value) => /^[0-9a-f]{40}(?:[0-9a-f]{24})?$/.test(value))
        || ![pending.expected_index_flags, pending.content_hash, pending.protected_hash].every(digest)
        || !safeRef(pending.ref)) fail('bad pending commit adoption');
    }
    for (const item of adoption.history) {
      if (!isObject(item) || typeof item.commit !== 'string' || typeof item.parent !== 'string'
        || !/^[0-9a-f]{40}(?:[0-9a-f]{24})?$/.test(item.commit)
        || !/^[0-9a-f]{40}(?:[0-9a-f]{24})?$/.test(item.parent)
        || typeof item.tree !== 'string' || !/^[0-9a-f]{40}(?:[0-9a-f]{24})?$/.test(item.tree)
        || !safeRef(item.ref) || !isStringArray(item.paths) || !item.paths.every(safeRelativePath)
        || !['claimed', 'building', 'built', 'in-review'].includes(item.execution_status)
        || typeof item.execution_hash !== 'string' || !/^[0-9a-f]{64}$/.test(item.execution_hash)
        || typeof item.adopted_at !== 'string') fail('bad commit adoption receipt');
    }
  }
  if (state.evidence_history !== undefined) {
    if (!Array.isArray(state.evidence_history)) fail('bad evidence history');
    for (const item of state.evidence_history) {
      if (!isObject(item) || typeof item.at !== 'string' || typeof item.reason !== 'string' || !item.reason.trim()
        || !isObject(item.details)
        || !Array.isArray(item.gates) || !(item.review === null || isObject(item.review))
        || !(item.verification === null || isObject(item.verification))) fail('bad evidence history item');
    }
  }
  if (state.completion_snapshot !== undefined) {
    const snap = state.completion_snapshot;
    if (!isObject(snap) || !isObject(snap.entries) || typeof snap.git_meta !== 'string'
      || snap.hash !== sha256(canonical({ entries: snap.entries, git_meta: snap.git_meta }))
      || state.phase !== 'finished' || snap.hash !== state.review?.snapshot_hash || snap.hash !== state.verification?.snapshot_hash) fail('bad completion snapshot');
  }
  for (const gate of state.gates) {
    if (!isObject(gate) || gate.provenance !== 'deliver-runtime-executed-v1' || typeof gate.name !== 'string'
      || typeof gate.command !== 'string' || !['PASS', 'FAIL'].includes(gate.status)
      || typeof gate.snapshot_hash !== 'string' || typeof gate.environment_hash !== 'string'
      || typeof gate.environment_additions_hash !== 'string') fail('bad gate receipt');
  }
  if (state.review !== null && (!isObject(state.review) || !['PASS', 'FAIL'].includes(state.review.status)
    || typeof state.review.builder !== 'string' || typeof state.review.reviewer !== 'string'
    || !Array.isArray(state.review.findings) || typeof state.review.snapshot_hash !== 'string')) fail('bad review');
  if (state.review?.panel !== undefined) {
    const panel = state.review.panel;
    if (!isObject(panel) || panel.snapshot_hash !== state.review.snapshot_hash || !Array.isArray(panel.members)
      || !panel.members.length || panel.members.length > 16) fail('bad review panel');
    for (const member of panel.members) {
      if (!isObject(member) || typeof member.lens !== 'string' || !/^[a-z][a-z0-9-]{0,63}$/.test(member.lens)
        || typeof member.reviewer !== 'string' || !['PASS', 'CONCERNS', 'FAIL'].includes(member.verdict)
        || member.snapshot_hash !== panel.snapshot_hash || !Array.isArray(member.findings)) fail('bad review panel member');
      for (const finding of member.findings) {
        if (!isObject(finding) || !['block', 'major', 'minor'].includes(finding.severity)
          || typeof finding.message !== 'string' || !finding.message.trim() || typeof finding.resolved !== 'boolean') fail('bad review panel finding');
      }
      if (member.verdict === 'PASS' && member.findings.some((finding) => !finding.resolved && finding.severity !== 'minor')) fail('invalid PASS panel member');
      if (member.verdict === 'CONCERNS' && !member.findings.some((finding) => !finding.resolved)) fail('invalid CONCERNS panel member');
    }
    if (new Set(panel.members.map((member) => member.lens)).size !== panel.members.length) fail('duplicate review panel lens');
    const derivedFindings = panel.members.flatMap((member) => member.findings
      .map((finding) => ({ ...finding, lens: member.lens, reviewer: member.reviewer })));
    const derivedStatus = panel.members.some((member) => member.verdict === 'FAIL')
      || derivedFindings.some((finding) => !finding.resolved && finding.severity !== 'minor') ? 'FAIL' : 'PASS';
    if (state.review.status !== derivedStatus || canonical(state.review.findings) !== canonical(derivedFindings)) fail('review panel aggregate is inconsistent');
  }
  if (state.verification !== null && (!isObject(state.verification) || typeof state.verification.verifier !== 'string'
    || !Array.isArray(state.verification.criteria) || typeof state.verification.snapshot_hash !== 'string')) fail('bad verification');
  if (['active', 'finished'].includes(state.phase) && (!state.task || !state.baseline)) fail('active/finished run needs a task and baseline');
  if (state.task && state.review) {
    if (state.review.builder !== state.task.builder || state.review.reviewer === state.task.builder) fail('review identity violates separation');
    for (const finding of state.review.findings) {
      if (!isObject(finding) || !['block', 'major', 'minor'].includes(finding.severity)
        || typeof finding.message !== 'string' || !finding.message.trim() || typeof finding.resolved !== 'boolean') fail('bad review finding');
    }
  }
  if (state.task && state.verification) {
    const expected = state.task.packet.acceptance.map((criterion) => criterion.id).sort();
    const actual = state.verification.criteria.map((criterion) => {
      if (!isObject(criterion) || typeof criterion.id !== 'string' || !['PASS', 'FAIL', 'UNKNOWN'].includes(criterion.status)
        || typeof criterion.evidence !== 'string' || !criterion.evidence.trim()) fail('bad verification criterion');
      return criterion.id;
    }).sort();
    if (canonical(actual) !== canonical(expected)) fail('verification criteria do not match acceptance');
    if (state.verification.verifier === state.task.builder) fail('verification identity violates separation');
    if (state.pm_binding?.format === 'current' && state.review?.reviewer === state.verification.verifier) {
      fail('current shared-project verifier must differ from reviewer');
    }
    if (state.pm_binding?.format === 'current'
      && state.review?.panel?.members.some((member) => member.reviewer === state.verification.verifier)) {
      fail('current shared-project verifier must differ from every panel reviewer');
    }
  }
  if (state.contracts !== undefined && state.contracts !== null) {
    if (!isObject(state.contracts) || !isObject(state.contracts.hashes) || !isStringArray(state.contracts.specs)
      || !isStringArray(state.contracts.editable_paths)) fail('bad frozen contracts');
    for (const [rel, hash] of Object.entries(state.contracts.hashes)) {
      if (path.isAbsolute(rel) || rel.split(/[\\/]/).includes('..') || !/^[0-9a-f]{64}$/.test(hash)) fail('unsafe contract hash');
    }
  }
  return state;
}

export function currentPlanHash(state) {
  if (state.plan.path === null) return state.plan.hash;
  try { return sha256(fs.readFileSync(state.plan.path)); }
  catch { return null; }
}

export function approvalIsCurrent(state) {
  const hash = currentPlanHash(state);
  return state.approval !== null && hash !== null && state.approval.plan_hash === hash;
}

export function syncPlan(state) {
  const hash = currentPlanHash(state);
  if (hash === null) throw new DeliverError(`plan is missing or unreadable: ${state.plan.path}`, 66);
  if (hash !== state.plan.hash) {
    archiveEvidence(state, 'plan_changed', { previous_plan_hash: state.plan.hash, next_plan_hash: hash });
    state.plan.hash = hash;
    state.approval = null;
    state.events.push({ at: new Date().toISOString(), type: 'plan_changed', plan_hash: hash });
  }
  return hash;
}

function checkedDirectory(dir, create) {
  try {
    const stat = fs.lstatSync(dir);
    if (!stat.isDirectory() || stat.isSymbolicLink()) throw new DeliverError(`runtime path must be a real directory: ${dir}`, 66);
  } catch (error) {
    if (error instanceof DeliverError) throw error;
    if (error.code !== 'ENOENT' || !create) throw new DeliverError(`runtime directory is unavailable: ${dir}`, 66);
    try { fs.mkdirSync(dir, { mode: 0o700 }); }
    catch (mkdirError) {
      if (mkdirError.code !== 'EEXIST') throw new DeliverError(`cannot create runtime directory: ${dir}`, 66);
    }
    const stat = fs.lstatSync(dir);
    if (!stat.isDirectory() || stat.isSymbolicLink()) throw new DeliverError(`runtime path must be a real directory: ${dir}`, 66);
  }
  return dir;
}

export function internalDirectory(projectRoot, segments, create = true) {
  const root = fs.realpathSync(projectRoot);
  let cursor = checkedDirectory(path.join(root, '.deliver'), create);
  for (const segment of segments) {
    if (!/^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/.test(segment)) throw new DeliverError('unsafe runtime directory segment', 66);
    cursor = checkedDirectory(path.join(cursor, segment), create);
  }
  return cursor;
}

function runsDir(projectRoot, create = true) { return internalDirectory(projectRoot, ['runs'], create); }

function atomicWrite(file, value, exclusive = false) {
  const temp = path.join(path.dirname(file), `.${path.basename(file)}.${process.pid}.${randomUUID()}.tmp`);
  fs.writeFileSync(temp, `${JSON.stringify(value, null, 2)}\n`, { mode: 0o600, flag: 'wx' });
  const tempFd = fs.openSync(temp, 'r');
  try { fs.fsyncSync(tempFd); } finally { fs.closeSync(tempFd); }
  try {
    if (exclusive && fs.existsSync(file)) throw new DeliverError(`run state already exists: ${file}`, 66);
    fs.renameSync(temp, file);
    let dirFd;
    try {
      dirFd = fs.openSync(path.dirname(file), 'r');
      fs.fsyncSync(dirFd);
    } catch (error) {
      if (process.platform !== 'win32') throw error;
    } finally { if (dirFd !== undefined) fs.closeSync(dirFd); }
  } finally {
    try { fs.unlinkSync(temp); } catch {}
  }
}

export function createRun(projectRoot, mode, planPath = null) {
  if (!['quick', 'managed', 'governed'].includes(mode)) throw new DeliverError('mode must be quick, managed, or governed', 64);
  const root = fs.realpathSync(projectRoot);
  if (!planPath && mode !== 'quick') throw new DeliverError('--plan is required in managed and governed modes', 64);
  const plan = planPath ? path.resolve(root, planPath) : null;
  let planHash = sha256('quick:no-plan');
  if (plan !== null) {
    try { planHash = sha256(fs.readFileSync(plan)); }
    catch (error) { throw new DeliverError(`cannot read plan: ${error.message}`, 66); }
  }
  const runId = randomUUID();
  const now = new Date().toISOString();
  const state = {
    schema_version: STATE_VERSION,
    run_id: runId,
    mode,
    revision: 0,
    project_root: root,
    created_at: now,
    updated_at: now,
    phase: 'initialized',
    plan: { path: plan, hash: planHash },
    approval: null,
    task: null,
    baseline: null,
    gates: [],
    review: null,
    verification: null,
    evidence_history: [],
    checkpoints: [],
    counters: { retries: 0, fixes: 0, corrections: 0 },
    events: [{ at: now, type: 'initialized', mode, plan_hash: planHash }],
  };
  const file = path.join(runsDir(root), `${runId}.json`);
  atomicWrite(file, state, true);
  return { state, file };
}

export function resolveRunPath(runArg, cwd = process.cwd()) {
  if (!runArg) throw new DeliverError('--run is required', 64);
  if (/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(runArg)) {
    let cursor = path.resolve(cwd);
    while (true) {
      const candidate = path.join(cursor, '.deliver', 'runs', `${runArg}.json`);
      if (fs.existsSync(candidate)) return candidate;
      const parent = path.dirname(cursor);
      if (parent === cursor) break;
      cursor = parent;
    }
    return path.join(cwd, '.deliver', 'runs', `${runArg}.json`);
  }
  return path.resolve(cwd, runArg);
}

export function readRun(runArg, cwd = process.cwd()) {
  const unresolvedFile = resolveRunPath(runArg, cwd);
  let file;
  let lexicalRoot;
  try {
    const runs = path.dirname(unresolvedFile);
    const deliver = path.dirname(runs);
    if (path.basename(runs) !== 'runs' || path.basename(deliver) !== '.deliver') throw new DeliverError('run state must be under .deliver/runs', 66);
    for (const dir of [deliver, runs]) {
      const stat = fs.lstatSync(dir);
      if (!stat.isDirectory() || stat.isSymbolicLink()) throw new DeliverError(`runtime path must be a real directory: ${dir}`, 66);
    }
    const stat = fs.lstatSync(unresolvedFile);
    if (!stat.isFile() || stat.isSymbolicLink()) throw new DeliverError('run state must be a regular file, not a symlink', 66);
    lexicalRoot = fs.realpathSync(path.dirname(deliver));
    file = fs.realpathSync(unresolvedFile);
    const expected = path.join(lexicalRoot, '.deliver', 'runs', path.basename(unresolvedFile));
    if (file !== expected) throw new DeliverError('run state is outside the canonical project runs directory', 66);
  } catch (error) {
    if (error instanceof DeliverError) throw error;
    throw new DeliverError(`cannot read run state: ${error.message}`, 66);
  }
  const state = validateRunState(readJsonFile(file, 'run state'));
  let actualRoot;
  try { actualRoot = fs.realpathSync(state.project_root); } catch { throw new DeliverError('run project root no longer exists', 66); }
  if (actualRoot !== state.project_root || actualRoot !== lexicalRoot) throw new DeliverError('run project root identity changed', 66);
  if (path.basename(file) !== `${state.run_id}.json`) throw new DeliverError('run filename does not match run_id', 66);
  return { state, file };
}

function acquireLock(file) {
  const lock = `${file}.lock`;
  let fd;
  try { fd = fs.openSync(lock, 'wx', 0o600); }
  catch (error) {
    if (error.code === 'EEXIST') throw new DeliverError(`run is locked by another process: ${lock}`, 66);
    throw error;
  }
  fs.writeFileSync(fd, `${process.pid} ${new Date().toISOString()}\n`);
  return () => { try { fs.closeSync(fd); } finally { try { fs.unlinkSync(lock); } catch {} } };
}

export function updateRun(runArg, expectedRevision, mutate, cwd = process.cwd()) {
  const file = readRun(runArg, cwd).file;
  const unlock = acquireLock(file);
  try {
    const { state } = readRun(file, cwd);
    if (expectedRevision !== undefined && state.revision !== expectedRevision) {
      throw new DeliverError(`revision conflict: expected ${expectedRevision}, found ${state.revision}`, 66);
    }
    const result = mutate(state);
    state.revision += 1;
    state.updated_at = new Date().toISOString();
    validateRunState(state);
    atomicWrite(file, state);
    return { state, file, result };
  } finally { unlock(); }
}

import fs from 'node:fs';
import path from 'node:path';
import { canonical, DeliverError, sha256 } from './state.mjs';

const MAX_STORY_BYTES = 8 * 1024 * 1024;
const EXECUTION_STATUSES = new Set(['claimed', 'building', 'built', 'in-review', 'blocked', 'merged']);
const BUILDERS = new Set(['auto', 'codex-builder', 'expert-builder']);
const RESERVED_KEYS = new Set(['__proto__', 'constructor', 'prototype']);
const fail = (message) => { throw new DeliverError(message, 66); };
const record = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);

function safeRelative(rel, label, prefix = null) {
  if (typeof rel !== 'string' || !rel || path.isAbsolute(rel) || /^[A-Za-z]:/.test(rel) || /[\x00-\x1f\x7f]/.test(rel)) fail(`unsafe ${label}`);
  const parts = rel.split(/[\\/]/);
  if (parts.some((part) => !part || part === '.' || part === '..')) fail(`unsafe ${label}`);
  const normalized = parts.join('/');
  if (prefix && !normalized.startsWith(prefix)) fail(`unsafe ${label}`);
  return normalized;
}

function storyPath(relPath) {
  const rel = safeRelative(relPath, 'story path', 'docs/stories/');
  if (!/^docs\/stories\/S\d+-\d+-[^/]+\.md$/.test(rel)) fail('story path must be docs/stories/S<digits>-<digits>-<name>.md');
  return rel;
}

function scopePath(value) {
  const rel = safeRelative(value, 'story touch path');
  if (/[?*\[\]{}<>]/.test(rel) || rel === '.git' || rel.startsWith('.git/')
    || rel === '.deliver' || rel.startsWith('.deliver/')) fail('story touch paths must be bounded repository paths');
  return rel;
}

function validateJson(value, label, depth = 0) {
  if (depth > 16) fail(`${label} is nested too deeply`);
  if (typeof value === 'string' && (value.length > 65536 || /[\x00-\x1f\x7f]/.test(value))) fail(`unsafe value in ${label}`);
  if (typeof value === 'number' && !Number.isFinite(value)) fail(`unsafe value in ${label}`);
  if (Array.isArray(value)) {
    for (const item of value) validateJson(item, label, depth + 1);
    return;
  }
  if (!record(value)) return;
  for (const [key, item] of Object.entries(value)) {
    if (RESERVED_KEYS.has(key) || /[\x00-\x1f\x7f]/.test(key)) fail(`unsafe field in ${label}`);
    validateJson(item, label, depth + 1);
  }
}

function parseCommentJson(text, kind) {
  const start = new RegExp(`<!--\\s*${kind}\\s*:`, 'g');
  const starts = [...text.matchAll(start)];
  const comments = [];
  for (const match of text.matchAll(/<!--([\s\S]*?)-->/g)) {
    const body = match[1].trim();
    if (!body.startsWith(`${kind}:`)) continue;
    comments.push({ raw: match[0], body: body.slice(kind.length + 1).trim(), index: match.index, end: match.index + match[0].length });
  }
  if (starts.length !== comments.length) fail(`malformed ${kind} comment`);
  if (comments.length !== 1) fail(`story needs exactly one ${kind} comment`);
  if (/\r|\n/.test(comments[0].body)) fail(`${kind} must contain one-line JSON`);
  let value;
  try { value = JSON.parse(comments[0].body); } catch { fail(`invalid JSON in ${kind}`); }
  if (!record(value)) fail(`${kind} must be a JSON object`);
  validateJson(value, kind);
  return { ...comments[0], value };
}

function optionalExecComment(text) {
  const starts = [...text.matchAll(/<!--\s*pm-exec\s*:/g)];
  const comments = [];
  for (const match of text.matchAll(/<!--([\s\S]*?)-->/g)) {
    const body = match[1].trim();
    if (!body.startsWith('pm-exec:')) continue;
    comments.push({ raw: match[0], body: body.slice('pm-exec:'.length).trim(), index: match.index, end: match.index + match[0].length });
  }
  if (starts.length !== comments.length) fail('malformed pm-exec comment');
  if (comments.length > 1) fail('story has duplicate pm-exec comments');
  if (!comments.length) return null;
  if (/\r|\n/.test(comments[0].body)) fail('pm-exec must contain one-line JSON');
  let value;
  try { value = JSON.parse(comments[0].body); } catch { fail('invalid JSON in pm-exec'); }
  if (!record(value)) fail('pm-exec must be a JSON object');
  validateJson(value, 'pm-exec');
  return { ...comments[0], value };
}

function cleanString(value, label, max = 512) {
  if (typeof value !== 'string' || !value || value.length > max || /[\x00-\x1f\x7f]/.test(value)) fail(`invalid ${label}`);
  return value;
}

export function isValidGitBranchName(value) {
  if (typeof value !== 'string' || !value || value.length > 512 || value === '@'
    || value.startsWith('-') || value.startsWith('/') || value.endsWith('/') || value.endsWith('.')
    || value.includes('..') || value.includes('//') || value.includes('@{')
    || /[\x00-\x20\x7f~^:?*[\\\]]/.test(value)) return false;
  return value.split('/').every((part) => part && !part.startsWith('.') && !part.endsWith('.lock'));
}

function normalizeMeta(meta) {
  if (!BUILDERS.has(meta.builder) || !Array.isArray(meta.touches) || !meta.touches.length) fail('invalid story pm-meta builder or touches');
  const touches = meta.touches.map(scopePath);
  if (new Set(touches).size !== touches.length) fail('story pm-meta touches must be unique');
  return { ...meta, builder: meta.builder, touches };
}

function normalizeExecution(value) {
  validateJson(value, 'pm-exec');
  const required = ['owner', 'builder', 'branch', 'status', 'rounds', 'retries', 'updated'];
  if (!required.every((key) => Object.hasOwn(value, key))) fail('pm-exec is missing required fields');
  cleanString(value.owner, 'pm-exec owner', 256);
  if (!['codex-builder', 'expert-builder'].includes(value.builder)) fail('invalid pm-exec builder');
  if (!isValidGitBranchName(value.branch)) fail('invalid pm-exec branch');
  if (!EXECUTION_STATUSES.has(value.status)) fail('invalid pm-exec status');
  for (const key of ['rounds', 'retries']) {
    if (!Number.isSafeInteger(value[key]) || value[key] < 0) fail(`invalid pm-exec ${key}`);
  }
  cleanString(value.updated, 'pm-exec updated', 128);
  return { ...value };
}

function sections(text, heading) {
  const source = heading === 'Execution'
    ? '^## Execution[ \\t]*\\r?$'
    : '^## Acceptance criteria(?: \\(testable\\))?[ \\t]*\\r?$';
  const re = new RegExp(source, 'gm');
  return [...text.matchAll(re)].map((match) => ({ index: match.index, end: match.index + match[0].length, raw: match[0] }));
}

function executionSection(text) {
  const found = sections(text, 'Execution');
  if (found.length > 1) fail('story has duplicate Execution sections');
  if (!found.length) return null;
  const section = found[0];
  if (/^## /m.test(text.slice(section.end).replace(/^\r?\n/, ''))) fail('Execution must be the final level-two section');
  return { start: section.index, headingEnd: section.end, end: text.length };
}

function splitList(value, label, pattern) {
  if (value.trim().toLowerCase() === 'none') return [];
  const items = value.split(',').map((item) => item.trim());
  if (!items.length || items.some((item) => !pattern.test(item)) || new Set(items).size !== items.length) fail(`invalid ${label}`);
  return items;
}

function parseHeaders(text, id) {
  const sprint = Number(id.match(/^S(\d+)-/)[1]);
  let priority = null;
  let covers = [];
  let dependsOn = [];
  let parallelSafe = null;
  let risk = null;
  let reviewLenses = [];
  let specs = [];
  const sprintLines = [...text.matchAll(/^Sprint:.*$/gm)];
  if (sprintLines.length > 1) fail('story has duplicate Sprint headers');
  if (sprintLines.length) {
    const match = sprintLines[0][0].match(/^Sprint:\s*(\d+)\s*·\s*Priority:\s*(high|med|low)\s*·\s*Covers:\s*(.*?)\s*·\s*Depends on:\s*(.*?)\s*·\s*Parallel-safe:\s*(yes|no)\s*$/);
    if (!match || Number(match[1]) !== sprint) fail('invalid story Sprint header');
    priority = match[2];
    covers = splitList(match[3], 'story Covers header', /^(?:US|FR|AC|SM)-\d+$/);
    dependsOn = splitList(match[4], 'story Depends on header', /^S\d+-\d+$/);
    parallelSafe = match[5] === 'yes';
  }
  const riskLines = [...text.matchAll(/^Risk:.*$/gm)];
  if (riskLines.length > 1) fail('story has duplicate Risk headers');
  if (riskLines.length) {
    const match = riskLines[0][0].match(/^Risk:\s*(low|med|high)\s*·\s*Review lenses:\s*(.*?)(?:\s*·\s*Specs:\s*(.*?))?\s*$/);
    if (!match) fail('invalid story Risk header');
    risk = match[1];
    reviewLenses = splitList(match[2], 'story Review lenses header', /^[a-z][a-z0-9-]*$/);
    specs = match[3] === undefined ? [] : splitList(match[3], 'story Specs header', /^(?!\/)[^\x00-\x1f\x7f*?\[\]{}<>]+\.sdd$/)
      .map((item) => safeRelative(item, 'story spec path'));
  }
  return { sprint, priority, covers, dependsOn, parallelSafe, risk, reviewLenses, specs };
}

function acceptanceCriteria(text) {
  const found = sections(text, 'Acceptance criteria');
  if (found.length !== 1) fail('story needs exactly one Acceptance criteria section');
  const start = found[0].end + (text.slice(found[0].end).match(/^\r?\n/)?.[0].length || 0);
  const next = text.slice(start).search(/^## /m);
  const end = next < 0 ? text.length : start + next;
  const criteria = [];
  for (const match of text.slice(start, end).matchAll(/^- \[([ xX])\] ([^\r\n]*)\r?$/gm)) {
    if (!match[2]) fail('acceptance criterion text must not be empty');
    const absolute = start + match.index;
    criteria.push({
      text: match[2],
      checked: match[1].toLowerCase() === 'x',
      line: text.slice(0, absolute).split(/\r?\n/).length,
    });
  }
  if (!criteria.length) fail('story needs explicit acceptance checkboxes');
  return criteria;
}

export function parseStory(text, relPath) {
  const rel = storyPath(relPath);
  if (typeof text !== 'string' || Buffer.byteLength(text) > MAX_STORY_BYTES || text.includes('\0')) fail('invalid or oversized story text');
  const heading = text.match(/^#\s+(S\d+-\d+)(?::|\s+[—-])\s*([^\r\n]+)\r?$/m);
  if (!heading || !heading[2] || /[\x00-\x1f\x7f]/.test(heading[2])) fail('story needs an ID and title heading');
  const fileId = path.basename(rel).match(/^(S\d+-\d+)-/)[1];
  if (heading[1] !== fileId) fail('story heading ID does not match its path');
  const metaComment = parseCommentJson(text, 'pm-meta');
  const metaLine = text.slice(0, metaComment.index).split(/\r?\n/).length;
  if (metaLine > 12) fail('pm-meta must appear in the first 12 lines');
  const meta = normalizeMeta(metaComment.value);
  const section = executionSection(text);
  const execComment = optionalExecComment(text);
  if (execComment && (!section || execComment.index < section.headingEnd)) fail('pm-exec must be inside the final Execution section');
  const execution = execComment ? normalizeExecution(execComment.value) : null;
  const contractText = section ? text.slice(0, section.start) : text;
  const headers = parseHeaders(contractText, heading[1]);
  const acceptance = acceptanceCriteria(contractText);
  return {
    id: heading[1],
    path: rel,
    title: heading[2],
    text,
    textHash: sha256(text),
    contractHash: sha256(contractText),
    meta,
    ...headers,
    acceptance,
    execution,
    executionHash: execution ? sha256(canonical(execution)) : null,
  };
}

export function readStory(root, relPath) {
  const rel = storyPath(relPath);
  let realRoot;
  try {
    const stat = fs.lstatSync(root);
    if (!stat.isDirectory() || stat.isSymbolicLink()) fail('project root must be a real directory');
    realRoot = fs.realpathSync.native(root);
  } catch (error) {
    if (error instanceof DeliverError) throw error;
    fail(`cannot read project root: ${error.message}`);
  }
  let cursor = realRoot;
  for (const part of rel.split('/')) {
    cursor = path.join(cursor, part);
    let stat;
    try { stat = fs.lstatSync(cursor); } catch (error) { fail(`cannot read story ${rel}: ${error.message}`); }
    if (stat.isSymbolicLink()) fail(`story path is a symlink: ${rel}`);
  }
  let stat;
  try { stat = fs.statSync(cursor); } catch (error) { fail(`cannot read story ${rel}: ${error.message}`); }
  if (!stat.isFile() || stat.size > MAX_STORY_BYTES) fail(`story must be a regular file no larger than ${MAX_STORY_BYTES} bytes: ${rel}`);
  return parseStory(fs.readFileSync(cursor, 'utf8'), rel);
}

export function storyTaskContract(document) {
  if (!record(document) || typeof document.contractHash !== 'string' || !record(document.meta) || !Array.isArray(document.acceptance)) fail('invalid StoryDocument');
  return {
    id: document.id,
    acceptanceText: document.acceptance.map((criterion) => criterion.text),
    touches: [...document.meta.touches],
    builder: document.meta.builder,
    specs: [...document.specs],
  };
}

export function replaceStoryExecution(document, nextExec, { note } = {}) {
  if (!record(document) || typeof document.text !== 'string' || typeof document.path !== 'string') fail('invalid StoryDocument');
  if (!record(nextExec)) fail('next execution must be a JSON object');
  const merged = normalizeExecution({ ...(document.execution || {}), ...nextExec });
  if (note !== undefined) cleanString(note, 'Execution note', 1000);
  const currentSection = executionSection(document.text);
  const currentComment = optionalExecComment(document.text);
  let retained = '';
  let prefix = document.text;
  if (currentSection) {
    prefix = document.text.slice(0, currentSection.start);
    retained = document.text.slice(currentSection.headingEnd).replace(/^\r?\n/, '');
    if (currentComment) {
      const offset = currentSection.headingEnd + (document.text.slice(currentSection.headingEnd).match(/^\r?\n/)?.[0].length || 0);
      const start = currentComment.index - offset;
      retained = `${retained.slice(0, start)}${retained.slice(start + currentComment.raw.length)}`;
    }
    retained = retained.replace(/^\r?\n+/, '').replace(/\s+$/, '');
  } else if (!prefix.endsWith('\n')) prefix += '\n';
  const lines = [`<!-- pm-exec: ${JSON.stringify(merged)} -->`];
  if (retained) lines.push(retained);
  if (note !== undefined) lines.push(`- ${note}`);
  const after = `${prefix}## Execution\n${lines.join('\n')}\n`;
  const nextDocument = parseStory(after, document.path);
  if (nextDocument.contractHash !== document.contractHash) fail('Execution replacement changed the story contract');
  return {
    before: document.text,
    after,
    contractHash: nextDocument.contractHash,
    executionHash: nextDocument.executionHash,
    document: nextDocument,
  };
}

import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { sha256, canonical, DeliverError } from './state.mjs';
import { changedContracts } from './contracts.mjs';
import { assertPmBinding } from './pm.mjs';

const toPosix = (value) => value.split(path.sep).join('/');
const hasControl = (value) => /[\x00-\x1f\x7f]/.test(value);
const isInside = (root, target) => {
  const relative = path.relative(root, target);
  return relative === '' || (!relative.startsWith(`..${path.sep}`) && relative !== '..' && !path.isAbsolute(relative));
};

export function git(root, args) {
  return execFileSync('git', ['-C', root, ...args], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], maxBuffer: 64 * 1024 * 1024, windowsHide: true });
}

export function gitRoot(cwd) {
  try { return fs.realpathSync(git(cwd, ['rev-parse', '--show-toplevel']).replace(/(\r?\n)+$/, '')); }
  catch { throw new DeliverError('Deliver must run inside a Git worktree', 66); }
}

function listZ(root, args) {
  return git(root, args).split('\0').filter(Boolean).map(toPosix);
}

function fingerprint(root, rel) {
  const abs = path.join(root, rel);
  let stat;
  try { stat = fs.lstatSync(abs); } catch { return null; }
  if (stat.isSymbolicLink()) return `symlink:${sha256(fs.readlinkSync(abs))}`;
  if (stat.isFile()) return `file:${stat.mode & 0o100 ? '755' : '644'}:${sha256(fs.readFileSync(abs))}`;
  throw new DeliverError(`unsupported repository path type: ${rel}`, 74);
}

function gitDirectories(root) {
  const safe = (args) => { try { return git(root, args); } catch { return ''; } };
  const gitDirRaw = safe(['rev-parse', '--git-dir']).replace(/(\r?\n)+$/, '');
  const gitDir = gitDirRaw ? path.resolve(root, gitDirRaw) : '';
  const commonDirRaw = safe(['rev-parse', '--git-common-dir']).replace(/(\r?\n)+$/, '');
  const commonDir = commonDirRaw ? path.resolve(root, commonDirRaw) : gitDir;
  return { safe, gitDir, commonDir };
}

function legacyProtectedGitMetadata(root) {
  const { gitDir, commonDir } = gitDirectories(root);
  const fileHash = (base, rel) => { try { return sha256(fs.readFileSync(path.join(base, rel))); } catch { return sha256(''); } };
  const hooks = [];
  try {
    for (const name of fs.readdirSync(path.join(commonDir, 'hooks')).sort()) hooks.push(`${name}:${fileHash(commonDir, path.join('hooks', name))}`);
  } catch {}
  return sha256(canonical({
    worktree_config: fileHash(gitDir, 'config.worktree'),
    common_config: fileHash(commonDir, 'config'),
    exclude: fileHash(commonDir, path.join('info', 'exclude')),
    hooks,
  }));
}

function effectiveHooks(root) {
  const { gitDir, commonDir } = gitDirectories(root);
  let configured = '';
  try { configured = git(root, ['config', '--path', '--get', 'core.hooksPath']).trim(); } catch {}
  const location = configured ? path.resolve(root, configured) : path.join(commonDir, 'hooks');
  const limit = 8 * 1024 * 1024;
  const result = { configured: configured || null, path: location, kind: 'missing', entries: [] };
  let locationStat;
  try { locationStat = fs.lstatSync(location); } catch (error) {
    if (error.code === 'ENOENT') return { result, active: false, upgrade_safe: true };
    throw new DeliverError(`cannot inspect effective Git hooks path: ${error.message}`, 66);
  }
  let directory = location;
  if (locationStat.isSymbolicLink()) {
    result.kind = 'symlink';
    result.target = fs.readlinkSync(location);
    try { directory = fs.realpathSync(location); } catch { throw new DeliverError('effective Git hooks path is a broken symlink', 66); }
    const resolved = fs.statSync(directory);
    if (!resolved.isDirectory()) throw new DeliverError('effective Git hooks path symlink must resolve to a directory', 66);
  } else if (locationStat.isDirectory()) {
    result.kind = 'directory';
  } else {
    throw new DeliverError('effective Git hooks path must be a directory or directory symlink', 66);
  }
  const names = fs.readdirSync(directory).sort();
  if (names.length > 1024) throw new DeliverError('effective Git hooks path has too many entries', 66);
  let total = 0;
  let active = false;
  for (const name of names) {
    if (hasControl(name)) throw new DeliverError('effective Git hooks path contains an unsafe entry name', 66);
    const file = path.join(directory, name);
    const stat = fs.lstatSync(file);
    const mode = stat.mode & 0o777;
    if (stat.isFile()) {
      if (stat.size > limit || total + stat.size > 32 * 1024 * 1024) throw new DeliverError('effective Git hooks exceed the protected metadata limit', 66);
      total += stat.size;
      result.entries.push({ name, kind: 'file', mode, hash: sha256(fs.readFileSync(file)) });
      if (!name.endsWith('.sample') && (mode & 0o111) !== 0) active = true;
      continue;
    }
    if (stat.isSymbolicLink()) {
      const target = fs.readlinkSync(file);
      const entry = { name, kind: 'symlink', mode, target };
      let resolved;
      try { resolved = fs.statSync(file); } catch { throw new DeliverError(`effective Git hook is a broken symlink: ${name}`, 66); }
      if (!resolved.isFile() || resolved.size > limit || total + resolved.size > 32 * 1024 * 1024) {
        throw new DeliverError(`effective Git hook symlink has an unsafe target: ${name}`, 66);
      }
      total += resolved.size;
      entry.target_mode = resolved.mode & 0o777;
      entry.target_hash = sha256(fs.readFileSync(file));
      result.entries.push(entry);
      if (!name.endsWith('.sample') && (entry.target_mode & 0o111) !== 0) active = true;
      continue;
    }
    throw new DeliverError(`effective Git hooks path contains a nonregular entry: ${name}`, 66);
  }
  return { result, active, upgrade_safe: !active };
}

export function protectedGitMetadata(root) {
  const { gitDir, commonDir } = gitDirectories(root);
  const fileHash = (base, rel) => { try { return sha256(fs.readFileSync(path.join(base, rel))); } catch { return sha256(''); } };
  return sha256(canonical({
    worktree_config: fileHash(gitDir, 'config.worktree'),
    common_config: fileHash(commonDir, 'config'),
    exclude: fileHash(commonDir, path.join('info', 'exclude')),
    hooks: effectiveHooks(root).result,
  }));
}

function initializedSubmodules(root) {
  const modules = [];
  for (const record of listZ(root, ['ls-files', '--stage', '-z'])) {
    const match = /^160000 [0-9a-f]+ [0-3]\t(.+)$/.exec(record);
    if (!match) continue;
    const rel = match[1];
    const candidate = path.join(root, rel);
    let stat;
    try { stat = fs.lstatSync(candidate); } catch { continue; }
    if (!stat.isDirectory() || stat.isSymbolicLink()) continue;
    const moduleRoot = fs.realpathSync(candidate);
    try {
      if (gitRoot(moduleRoot) === moduleRoot) modules.push({ rel, root: moduleRoot });
    } catch {}
  }
  return modules.sort((left, right) => left.rel.localeCompare(right.rel));
}

function captureNestedGitAnchor(root) {
  const anchor = {
    metadata_version: 'protected-v2',
    head: git(root, ['rev-parse', '--verify', 'HEAD']).trim(),
    tree: git(root, ['rev-parse', 'HEAD^{tree}']).trim(),
    index_tree: git(root, ['write-tree']).trim(),
    index_flags: sha256(git(root, ['ls-files', '-v', '-z'])),
    protected_hash: protectedGitMetadata(root),
  };
  if (!anchor.head || !anchor.tree || !anchor.index_tree) throw new Error('unborn nested repository');
  const submodules = Object.fromEntries(initializedSubmodules(root)
    .map((module) => [module.rel, captureNestedGitAnchor(module.root)]));
  if (Object.keys(submodules).length) anchor.submodules = submodules;
  return anchor;
}

export function captureGitAnchor(root) {
  try {
    const head = git(root, ['rev-parse', '--verify', 'HEAD']).trim();
    const ref = git(root, ['symbolic-ref', '-q', 'HEAD']).trim();
    const tree = git(root, ['rev-parse', 'HEAD^{tree}']).trim();
    const indexTree = git(root, ['write-tree']).trim();
    if (!head || !ref.startsWith('refs/heads/') || !tree || !indexTree) throw new Error('unborn or detached HEAD');
    const anchor = {
      metadata_version: 'protected-v2',
      head,
      ref,
      tree,
      index_tree: indexTree,
      index_flags: sha256(git(root, ['ls-files', '-v', '-z'])),
      protected_hash: protectedGitMetadata(root),
    };
    const submodules = Object.fromEntries(initializedSubmodules(root)
      .map((module) => [module.rel, captureNestedGitAnchor(module.root)]));
    if (Object.keys(submodules).length) anchor.submodules = submodules;
    return anchor;
  } catch (error) {
    if (error instanceof DeliverError) throw error;
    throw new DeliverError(`cannot capture protected Git anchor: ${error.message}`, 66);
  }
}

export function legacyAnchorUpgradeSafe(root) {
  if (!effectiveHooks(root).upgrade_safe) return false;
  return initializedSubmodules(root).every((module) => legacyAnchorUpgradeSafe(module.root));
}

function rootAnchor(anchor) {
  const { submodules: _submodules, ...root } = anchor;
  return root;
}

function protectedV1Compatible(root, stored, current) {
  if (stored.metadata_version !== undefined) return false;
  const { metadata_version: _version, ...currentV1Shape } = current;
  if (canonical(stored) === canonical(currentV1Shape)) return true;
  if (!legacyAnchorUpgradeSafe(root) || stored.protected_hash !== legacyProtectedGitMetadata(root)) return false;
  return canonical({ ...stored, protected_hash: current.protected_hash }) === canonical(currentV1Shape);
}

function nestedMetadata(entries) {
  const result = Object.create(null);
  for (const [rel, value] of Object.entries(entries)) {
    const match = /^gitlink:[0-9a-f]+:([0-9a-f]{64})$/.exec(value);
    if (match) result[rel] = match[1];
  }
  return result;
}

function gitMetadata(root) {
  const { safe } = gitDirectories(root);
  return sha256(canonical({
    head: safe(['rev-parse', '--verify', 'HEAD']).trim() || 'UNBORN',
    ref: safe(['symbolic-ref', '-q', 'HEAD']).trim() || 'DETACHED',
    tree: safe(['rev-parse', 'HEAD^{tree}']).trim(),
    index_tree: safe(['write-tree']).trim(),
    index_flags: sha256(safe(['ls-files', '-v', '-z'])),
    protected_hash: protectedGitMetadata(root),
    index: sha256(safe(['diff', '--cached', '--binary', '--no-ext-diff', '--no-textconv'])),
    // Other branches and worktrees can advance independently. Protect this
    // checkout's HEAD/index and shared configuration, not unrelated refs.
  }));
}

function legacyGitMetadataV1(root) {
  const { safe, gitDir, commonDir } = gitDirectories(root);
  const fileHash = (base, rel) => { try { return sha256(fs.readFileSync(path.join(base, rel))); } catch { return sha256(''); } };
  const hooks = [];
  try {
    for (const name of fs.readdirSync(path.join(commonDir, 'hooks')).sort()) {
      hooks.push(`${name}:${fileHash(commonDir, path.join('hooks', name))}`);
    }
  } catch {}
  return sha256(canonical({
    head: safe(['rev-parse', '--verify', 'HEAD']).trim() || 'UNBORN',
    ref: safe(['symbolic-ref', '-q', 'HEAD']).trim() || 'DETACHED',
    index: sha256(safe(['diff', '--cached', '--binary', '--no-ext-diff', '--no-textconv'])),
    index_flags: sha256(safe(['ls-files', '-s', '-v', '-z'])),
    worktree_config: fileHash(gitDir, 'config.worktree'),
    common_config: fileHash(commonDir, 'config'),
    exclude: fileHash(commonDir, path.join('info', 'exclude')),
    hooks,
  }));
}

const protectedIgnored = (rel) => /(^|\/)(?:AGENTS|CLAUDE)\.md$/.test(rel)
  || /(^|\/)\.(?:agents|codex)(?:\/|$)/.test(rel)
  || rel.endsWith('.sdd') || /(^|\/)\.specdd(?:\/|$)/.test(rel)
  || /(^|\/)(?:config|configs|contract|contracts)(?:[./]|$)/.test(rel);

const covers = (scope, rel) => scope === '.' || rel === scope || rel.startsWith(`${scope}/`);

function resolvedInputs(root, paths) {
  const result = new Set(paths);
  const visited = new Set();
  function visit(abs) {
    let stat;
    try { stat = fs.lstatSync(abs); } catch (error) {
      if (error.code === 'ENOENT') return;
      throw error;
    }
    const real = fs.realpathSync(abs);
    const rel = toPosix(path.relative(root, real)) || '.';
    if (!isInside(root, real) || /^(?:\.git|\.deliver)(?:\/|$)/.test(rel)) {
      throw new DeliverError(`declared input resolves outside code snapshot: ${abs}`, 74);
    }
    if (stat.isSymbolicLink() || abs !== real) result.add(rel);
    if (visited.has(real)) return;
    visited.add(real);
    if (fs.statSync(real).isDirectory()) {
      for (const name of fs.readdirSync(real)) {
        if (name === '.git' || name === '.deliver') continue;
        visit(path.join(real, name));
      }
    }
  }
  for (const rel of paths) visit(path.join(root, rel));
  return [...result];
}

function snapshotVersion(root, relevantPaths, metadataVersion) {
  root = fs.realpathSync(root);
  relevantPaths = resolvedInputs(root, relevantPaths);
  const gitlinks = new Map(listZ(root, ['ls-files', '--stage', '-z']).flatMap((record) => {
    const match = /^160000 ([0-9a-f]+) [0-3]\t(.+)$/.exec(record);
    return match ? [[match[2], match[1]]] : [];
  }));
  const authoritative = new Set([
    ...listZ(root, ['ls-files', '-z']),
    ...listZ(root, ['ls-files', '--others', '--exclude-standard', '-z']),
  ]);
  const ignored = listZ(root, ['ls-files', '--others', '--ignored', '--exclude-standard', '-z'])
    .filter((rel) => !rel.startsWith('.deliver/'));
  for (const rel of ignored) if (protectedIgnored(rel) || relevantPaths.some((scope) => covers(scope, rel))) authoritative.add(rel);
  const entries = Object.create(null);
  const submoduleMetadata = Object.create(null);
  for (const rel of [...authoritative].sort()) {
    if (rel.startsWith('.deliver/')) continue;
    if (hasControl(rel)) throw new DeliverError(`unsupported control character in path: ${JSON.stringify(rel)}`, 74);
    if (gitlinks.has(rel) && fs.existsSync(path.join(root, rel)) && fs.lstatSync(path.join(root, rel)).isDirectory()) {
      const moduleRoot = fs.realpathSync(path.join(root, rel));
      const initialized = gitRoot(moduleRoot) === moduleRoot;
      if (!initialized) {
        if (fs.readdirSync(moduleRoot).length) throw new DeliverError(`uninitialized submodule contains files: ${rel}`, 74);
        entries[rel] = `gitlink:${gitlinks.get(rel)}:uninitialized`;
        continue;
      }
      const moduleInputs = relevantPaths.flatMap((scope) => covers(scope, rel) ? ['.'] : covers(rel, scope) ? [scope.slice(rel.length + 1)] : []);
      const nested = snapshotVersion(moduleRoot, moduleInputs, metadataVersion);
      submoduleMetadata[rel] = nested.git_meta;
      entries[rel] = `gitlink:${gitlinks.get(rel)}:${nested.git_meta}`;
      for (const [file, value] of Object.entries(nested.entries)) entries[`${rel}/${file}`] = value;
      continue;
    }
    const value = fingerprint(root, rel);
    if (value !== null) entries[rel] = value;
  }
  const ignoredAdvisory = Object.create(null);
  for (const rel of ignored.sort()) {
    if (authoritative.has(rel)) continue;
    try {
      const stat = fs.lstatSync(path.join(root, rel));
      ignoredAdvisory[rel] = { size: stat.size, mtime_ms: Math.trunc(stat.mtimeMs), kind: stat.isSymbolicLink() ? 'symlink' : 'file' };
    } catch {}
  }
  const localMetadata = metadataVersion === 'legacy-v1' ? legacyGitMetadataV1(root) : gitMetadata(root);
  const gitMeta = gitlinks.size ? sha256(canonical({ local: localMetadata, submodules: submoduleMetadata })) : localMetadata;
  return { entries, git_meta: gitMeta, ignored_advisory: ignoredAdvisory, hash: sha256(canonical({ entries, git_meta: gitMeta })) };
}

export function snapshot(root, relevantPaths = []) {
  return snapshotVersion(root, relevantPaths, 'current');
}

function legacySnapshotV1(root, relevantPaths = []) {
  return snapshotVersion(root, relevantPaths, 'legacy-v1');
}

export function baselineDirtyPaths(root) {
  const out = listZ(root, ['status', '--porcelain=v1', '-z', '--untracked-files=all']);
  const paths = [];
  for (let i = 0; i < out.length; i++) {
    const record = out[i];
    if (record.length < 4) continue;
    const status = record.slice(0, 2);
    const rel = record.slice(3);
    paths.push(rel);
    if ((status[0] === 'R' || status[0] === 'C') && out[i + 1]) paths.push(out[++i]);
  }
  return [...new Set(paths.filter((rel) => !rel.startsWith('.deliver/')))].sort();
}

function validateRelativePath(root, raw, kind) {
  if (typeof raw !== 'string' || raw === '' || path.isAbsolute(raw) || hasControl(raw)) throw new DeliverError(`invalid ${kind} path: ${JSON.stringify(raw)}`, 66);
  const rel = toPosix(path.posix.normalize(toPosix(raw).replace(/\/$/, '')));
  if (rel === '.' || rel === '..' || rel.startsWith('../') || /[*?\[\]{}<>]/.test(rel)) throw new DeliverError(`invalid ${kind} path: ${raw}`, 66);
  if (rel === '.git' || rel.startsWith('.git/') || rel === '.deliver' || rel.startsWith('.deliver/')) throw new DeliverError(`${kind} may not grant ${rel}`, 66);
  const segments = rel.split('/');
  let current = root;
  for (const segment of segments) {
    current = path.join(current, segment);
    let stat;
    try { stat = fs.lstatSync(current); } catch { break; }
    if (stat.isSymbolicLink()) {
      if (kind === 'touches') throw new DeliverError(`touches may not traverse a symlink: ${rel}`, 66);
      let resolved;
      try { resolved = fs.realpathSync(current); } catch { throw new DeliverError(`${kind} crosses a broken symlink: ${rel}`, 66); }
      const inside = isInside(root, resolved);
      if (!inside) throw new DeliverError(`${kind} escapes the worktree through a symlink: ${rel}`, 66);
      current = resolved;
    }
  }
  return rel;
}

export function validateTaskPaths(root, packet) {
  packet.touches = [...new Set(packet.touches.map((value) => validateRelativePath(root, value, 'touches')))].sort();
  packet.read_paths = [...new Set(packet.read_paths.map((value) => validateRelativePath(root, value, 'read_paths')))].sort();
  packet.specs = [...new Set(packet.specs.map((value) => validateRelativePath(root, value, 'specs')))].sort();
  for (const touch of packet.touches) assertNoEscapingSymlinks(root, touch);
  return packet;
}

function assertNoEscapingSymlinks(root, rel) {
  const abs = path.join(root, rel);
  let stat;
  try { stat = fs.lstatSync(abs); } catch { return; }
  if (stat.isSymbolicLink()) {
    throw new DeliverError(`touches contains a symlink; use an explicit non-aliased scope: ${rel}`, 66);
  }
  if (!stat.isDirectory()) return;
  for (const entry of fs.readdirSync(abs, { withFileTypes: true })) {
    if (rel === '.' && (entry.name === '.git' || entry.name === '.deliver')) continue;
    assertNoEscapingSymlinks(root, `${rel}/${entry.name}`.replace(/^\.\//, ''));
  }
}

const allowed = (rel, touches) => touches.some((scope) => rel === scope || rel.startsWith(`${scope}/`));

function symlinkEscapes(root, rel) {
  let stat;
  try { stat = fs.lstatSync(path.join(root, rel)); } catch { return false; }
  if (!stat.isSymbolicLink()) return false;
  const target = path.resolve(path.dirname(path.join(root, rel)), fs.readlinkSync(path.join(root, rel)));
  return !isInside(root, target);
}

export function compareSnapshots(root, baseline, current, touches, dirtyAtStart = [], { ignoreGitMetadata = false } = {}) {
  const before = baseline.entries;
  const after = current.entries;
  const changed = [...new Set([...Object.keys(before), ...Object.keys(after)])]
    .filter((rel) => before[rel] !== after[rel]).sort();
  const deleted = changed.filter((rel) => Object.hasOwn(before, rel) && !Object.hasOwn(after, rel));
  const added = changed.filter((rel) => !Object.hasOwn(before, rel) && Object.hasOwn(after, rel));
  const renames = [];
  const used = new Set();
  for (const from of deleted) {
    const to = added.find((candidate) => !used.has(candidate) && before[from] === after[candidate]);
    if (to) { used.add(to); renames.push({ from, to }); }
  }
  const outOfScope = changed.filter((rel) => !allowed(rel, touches));
  const preexistingDirtyChanged = changed.filter((rel) => dirtyAtStart.some((dirty) => covers(dirty, rel)));
  const symlinkEscapesFound = changed.filter((rel) => symlinkEscapes(root, rel));
  const gitChanged = !ignoreGitMetadata && baseline.git_meta !== current.git_meta;
  const ignoredAdvisoryChanged = [...new Set([
    ...Object.keys(baseline.ignored_advisory || {}),
    ...Object.keys(current.ignored_advisory || {}),
  ])].filter((rel) => canonical(baseline.ignored_advisory?.[rel]) !== canonical(current.ignored_advisory?.[rel])).sort();
  return {
    ok: outOfScope.length === 0 && preexistingDirtyChanged.length === 0 && symlinkEscapesFound.length === 0 && !gitChanged,
    changed,
    added,
    deleted,
    renames,
    out_of_scope: outOfScope,
    preexisting_dirty_changed: preexistingDirtyChanged,
    symlink_escapes: symlinkEscapesFound,
    git_metadata_changed: gitChanged,
    ignored_advisory_changed: ignoredAdvisoryChanged,
  };
}

export function inspectScope(state, { allowPendingAdoption = false, ignoreGitAnchor = false } = {}) {
  assertPmBinding(state);
  if (!state.baseline || !state.task) throw new DeliverError('task has no baseline; run start first', 66);
  if (state.commit_adoption?.pending && !allowPendingAdoption) throw new DeliverError('commit adoption is pending; commit or reconcile it before continuing', 66);
  validateTaskPaths(state.project_root, state.task.packet);
  const relevantPaths = [...state.task.packet.touches, ...state.task.packet.read_paths, ...state.task.packet.specs];
  const current = snapshot(state.project_root, relevantPaths);
  const baselineForComparison = state.baseline.snapshot;
  let currentForComparison = current;
  let metadataCompatibility = null;
  if (state.baseline_metadata_version === 'legacy-v1') {
    currentForComparison = legacySnapshotV1(state.project_root, relevantPaths);
    metadataCompatibility = 'legacy-v1';
  } else if (!state.git_anchor && baselineForComparison.git_meta !== current.git_meta) {
    const legacyCurrent = legacySnapshotV1(state.project_root, relevantPaths);
    if (baselineForComparison.git_meta === legacyCurrent.git_meta) {
      currentForComparison = legacyCurrent;
      metadataCompatibility = 'legacy-v1';
    }
  }
  let coordinatorExecutionChanged = null;
  if (state.execution_audit) {
    const audit = state.execution_audit;
    if (baselineForComparison.entries[audit.story_path] !== audit.original_entry
      || current.entries[audit.story_path] !== audit.current_entry) {
      throw new DeliverError('audited Execution entry does not match the original baseline or current story', 66);
    }
    const entries = { ...currentForComparison.entries };
    if (audit.original_entry === null) delete entries[audit.story_path];
    else entries[audit.story_path] = audit.original_entry;
    currentForComparison = { ...currentForComparison, entries };
    coordinatorExecutionChanged = audit.story_path;
  }
  const report = compareSnapshots(state.project_root, baselineForComparison, currentForComparison,
    state.task.packet.touches, state.baseline.dirty_paths, { ignoreGitMetadata: Boolean(state.git_anchor) });
  if (state.git_anchor && !ignoreGitAnchor) {
    const anchor = captureGitAnchor(state.project_root);
    const exact = canonical(anchor) === canonical(state.git_anchor);
    const protectedCompatible = !exact && protectedV1Compatible(state.project_root, state.git_anchor, anchor);
    const flatRoot = rootAnchor(anchor);
    const flatRootCompatible = canonical(flatRoot) === canonical(state.git_anchor)
      || protectedV1Compatible(state.project_root, state.git_anchor, flatRoot);
    const flatCompatible = !exact && !protectedCompatible && state.git_anchor.submodules === undefined
      && anchor.submodules !== undefined
      && flatRootCompatible
      && canonical(nestedMetadata(baselineForComparison.entries)) === canonical(nestedMetadata(currentForComparison.entries))
      && legacyAnchorUpgradeSafe(state.project_root);
    report.git_metadata_changed = !exact && !protectedCompatible && !flatCompatible;
    if (protectedCompatible) report.git_anchor_compatibility = 'protected-v1';
    if (flatCompatible) report.git_anchor_compatibility = 'flat-v1';
    if (report.git_metadata_changed) report.ok = false;
  }
  report.coordinator_execution_changed = coordinatorExecutionChanged;
  report.git_metadata_compatibility = metadataCompatibility;
  report.contracts_changed = [...new Set([...changedContracts(state), ...(state.contracts
    ? report.changed.filter((rel) => rel.endsWith('.sdd') || /(^|\/)\.specdd(?:\/|$)/.test(rel)) : [])])].sort();
  if (report.contracts_changed.length) report.ok = false;
  return { current, report };
}

import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { randomUUID } from 'node:crypto';
import { canonical, sha256, DeliverError, internalDirectory } from './state.mjs';
import { inspectScope } from './scope.mjs';

const MAX_OUTPUT = 1024 * 1024;

export function parseEnvironment(file) {
  if (!file) return {};
  let value;
  try { value = JSON.parse(fs.readFileSync(file, 'utf8')); }
  catch (error) { throw new DeliverError(`invalid gate environment JSON: ${error.message}`, 64); }
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new DeliverError('gate environment must be a JSON object', 64);
  for (const [key, item] of Object.entries(value)) {
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(key) || typeof item !== 'string' || item.includes('\0')) throw new DeliverError(`invalid gate environment entry: ${key}`, 64);
  }
  return value;
}

function additionsHash(additions) { return sha256(canonical(additions)); }

export function environmentHandle(cwd, environmentAdditionsHash) {
  // Hash all inherited values, never persist the values themselves. Exclude
  // shell bookkeeping that does not describe the command's effective inputs.
  const inherited = Object.fromEntries(Object.entries(process.env).filter(([key]) => !['_', 'SHLVL', 'OLDPWD'].includes(key)));
  return sha256(canonical({ cwd: fs.realpathSync(cwd), inherited, environment_additions_hash: environmentAdditionsHash }));
}

function safeCwd(root, raw = '.') {
  const abs = path.resolve(root, raw);
  let real;
  try { real = fs.realpathSync(abs); } catch { throw new DeliverError(`gate cwd does not exist: ${raw}`, 66); }
  const relative = path.relative(root, real);
  if (relative === '..' || relative.startsWith(`..${path.sep}`) || path.isAbsolute(relative)) throw new DeliverError('gate cwd escapes the project root', 66);
  return real;
}

export function executeGate(state, { name, command, cwd = '.', environment = {} }) {
  if (!/^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/.test(name || '')) throw new DeliverError('gate name must be a safe identifier', 64);
  if (typeof command !== 'string' || command.trim() === '' || command.includes('\0')) throw new DeliverError('--command must be a non-empty exact shell command', 64);
  const gateCwd = safeCwd(state.project_root, cwd);
  if (gateCwd !== state.project_root) throw new DeliverError('declared gates run at the project root; include an explicit directory change in the approved command', 66);
  const environmentAdditionsHash = additionsHash(environment);
  const logDir = internalDirectory(state.project_root, ['logs', state.run_id]);
  const logPath = path.join(logDir, `${name}-${randomUUID()}.log`);
  try {
    fs.lstatSync(logPath);
    throw new DeliverError(`gate log target already exists: ${logPath}`, 66);
  } catch (error) {
    if (error instanceof DeliverError) throw error;
    if (error.code !== 'ENOENT') throw new DeliverError(`cannot inspect gate log target: ${error.message}`, 66);
  }
  const before = inspectScope(state);
  if (!before.report.ok) throw new DeliverError('gate refused because the current scope check fails', 74, before.report);
  const started = new Date().toISOString();
  const result = spawnSync(command, {
    cwd: gateCwd,
    env: { ...process.env, ...environment },
    encoding: 'utf8',
    shell: true,
    windowsHide: true,
    maxBuffer: MAX_OUTPUT,
    timeout: 10 * 60 * 1000,
  });
  const { current, report } = inspectScope(state);
  const stdout = String(result.stdout || '');
  const stderr = String(result.stderr || '');
  try {
    fs.writeFileSync(logPath, `command: ${command}\ncwd: ${gateCwd}\nstarted: ${started}\nexit: ${result.status ?? 'null'}\n\n[stdout]\n${stdout}\n[stderr]\n${stderr}`, { mode: 0o600, flag: 'wx' });
  } catch (error) { throw new DeliverError(`cannot create exclusive gate log: ${error.message}`, 66); }
  // A formatter or generator can change code after its checks have run. Its
  // exit status cannot verify that new tree. Require a stable follow-up gate.
  const mutated = before.current.hash !== current.hash;
  const passed = result.status === 0 && !result.error && report.ok && !mutated;
  return {
    provenance: 'deliver-runtime-executed-v1',
    name,
    command,
    cwd: path.relative(state.project_root, gateCwd).split(path.sep).join('/') || '.',
    environment_keys: Object.keys(environment).sort(),
    environment_additions_hash: environmentAdditionsHash,
    environment_hash: environmentHandle(gateCwd, environmentAdditionsHash),
    snapshot_hash: current.hash,
    status: passed ? 'PASS' : 'FAIL',
    exit_code: result.status,
    signal: result.signal || null,
    error: result.error ? result.error.message : mutated ? 'gate changed authoritative files; rerun a non-mutating check against the resulting tree' : null,
    log_path: path.relative(state.project_root, logPath).split(path.sep).join('/'),
    output: { stdout_bytes: Buffer.byteLength(stdout), stderr_bytes: Buffer.byteLength(stderr), truncated: result.error?.code === 'ENOBUFS' },
    scope: report,
    started_at: started,
    finished_at: new Date().toISOString(),
  };
}

export function gateIsCurrent(state, gate, snapshotHash) {
  if (!gate || gate.provenance !== 'deliver-runtime-executed-v1' || gate.status !== 'PASS' || gate.snapshot_hash !== snapshotHash) return false;
  const cwd = safeCwd(state.project_root, gate.cwd);
  return gate.environment_hash === environmentHandle(cwd, gate.environment_additions_hash);
}

import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync, spawnSync } from 'node:child_process';
import { test } from 'node:test';
import { fileURLToPath } from 'node:url';
import { readStory } from '../plugins/deliver/skills/deliver/scripts/lib/story.mjs';
import { canonical, sha256 } from '../plugins/deliver/skills/deliver/scripts/lib/state.mjs';
import { inspectState as upstreamInspect, parseExec as upstreamExecution } from './fixtures/upstream-v0.25.1/hooks/lib.mjs';

const runtime = fileURLToPath(new URL('../plugins/deliver/skills/deliver/scripts/deliver.mjs', import.meta.url));
const pmCli = fileURLToPath(new URL('../plugins/deliver/skills/deliver/scripts/pm.mjs', import.meta.url));
const storyRel = 'docs/stories/S1-1-value.md';
const criterion = 'The integrated value is present.';

function git(root, ...args) {
  return execFileSync('git', ['-C', root, ...args], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trimEnd();
}

function write(root, rel, value) {
  const file = path.join(root, rel);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, typeof value === 'string' ? value : `${JSON.stringify(value, null, 2)}\n`);
  return file;
}

function call(root, file, ...args) {
  const result = spawnSync(process.execPath, [file, ...args], { cwd: root, encoding: 'utf8' });
  let json;
  try { json = JSON.parse(result.stdout); } catch { json = null; }
  return { ...result, json };
}

function story(touches = ['src'], specs = []) {
  return [
    '# S1-1: Change value',
    `<!-- pm-meta: ${JSON.stringify({ builder: 'codex-builder', touches })} -->`,
    'Sprint: 1 · Priority: high · Covers: AC-001 · Depends on: none · Parallel-safe: yes',
    `Risk: low · Review lenses: code-integrity-reviewer · Specs: ${specs.length ? specs.join(', ') : 'none'}`,
    '',
    '## Goal',
    'Change the value.',
    '',
    '## Acceptance criteria (testable)',
    `- [ ] ${criterion}`,
    '',
    '## Verification',
    '- Run the declared test gate.',
    '',
  ].join('\n');
}

function finishedCandidate(t, {
  preexistingDirty = false, gateCommand = 'node -e "process.exit(0)"', withSubmodule = false, advanceSubmodule = false,
  sourceConcern = false, nestedSubmoduleScopes = false, deepSubmodule = false, bindSubmodule = true,
  ignoreSubmoduleStatus = false, initializeIntegrationSubmodule = true,
} = {}) {
  const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'deliver-integration-source-')));
  const integration = `${root}-integration`;
  t.after(() => fs.rmSync(root, { recursive: true, force: true }));
  t.after(() => fs.rmSync(integration, { recursive: true, force: true }));
  git(root, 'init', '-q', '--initial-branch=main');
  git(root, 'config', 'user.name', 'Casey Example');
  git(root, 'config', 'user.email', 'casey@example.invalid');
  let dependency = null;
  let leafDependency = null;
  if (withSubmodule) {
    dependency = `${root}-dependency`;
    t.after(() => fs.rmSync(dependency, { recursive: true, force: true }));
    fs.mkdirSync(dependency);
    git(dependency, 'init', '-q', '--initial-branch=main');
    git(dependency, 'config', 'user.name', 'Dependency Author');
    git(dependency, 'config', 'user.email', 'dependency@example.invalid');
    write(dependency, 'value.txt', 'dependency v1\n');
    if (nestedSubmoduleScopes) {
      write(dependency, 'contract.sdd', 'Spec: Dependency contract\nPurpose:\n  Bind the nested integration fixture.\nOwns:\n  ./value.txt\n  ./nested/leaf/leaf.txt\n  ../../src\nMust:\n  Preserve the committed value.\nDone when:\n  The committed value is verified.\n');
      fs.symlinkSync('value.txt', path.join(dependency, 'value-link'));
    }
    if (deepSubmodule) {
      leafDependency = `${root}-leaf-dependency`;
      t.after(() => fs.rmSync(leafDependency, { recursive: true, force: true }));
      fs.mkdirSync(leafDependency);
      git(leafDependency, 'init', '-q', '--initial-branch=main');
      git(leafDependency, 'config', 'user.name', 'Leaf Author');
      git(leafDependency, 'config', 'user.email', 'leaf@example.invalid');
      write(leafDependency, 'leaf.txt', 'leaf v1\n');
      git(leafDependency, 'add', 'leaf.txt');
      git(leafDependency, 'commit', '-qm', 'Leaf v1');
      git(dependency, '-c', 'protocol.file.allow=always', 'submodule', 'add', '-q', leafDependency, 'nested/leaf');
    }
    git(dependency, 'add', '-A');
    git(dependency, 'commit', '-qm', 'Dependency v1');
    git(root, '-c', 'protocol.file.allow=always', 'submodule', 'add', '-q', dependency, 'vendor/dependency');
    if (deepSubmodule) git(root, '-c', 'protocol.file.allow=always', 'submodule', 'update', '--init', '--recursive', '-q');
    if (ignoreSubmoduleStatus) {
      git(root, 'config', '-f', '.gitmodules', 'submodule.vendor/dependency.ignore', 'all');
      git(root, 'add', '.gitmodules');
    }
  }
  const pm = (...args) => call(root, pmCli, ...args);
  const run = (...args) => call(root, runtime, ...args);
  assert.equal(pm('init').status, 0);
  write(root, 'docs/plan.md', '# Plan\n\n## Delivery mode\n- Scale: standard\n- Checkpoint policy: story-level\n- Integration branch: main\n- Skeleton: none\n');
  const touches = withSubmodule && bindSubmodule
    ? ['src', nestedSubmoduleScopes ? (deepSubmodule ? 'vendor/dependency/nested/leaf/leaf.txt' : 'vendor/dependency/value.txt') : 'vendor/dependency']
    : ['src'];
  const specs = withSubmodule && nestedSubmoduleScopes ? ['vendor/dependency/contract.sdd'] : [];
  const readPaths = [storyRel, ...(withSubmodule && nestedSubmoduleScopes
    ? ['vendor/dependency/value-link', 'vendor/dependency/missing.txt'] : [])];
  write(root, storyRel, story(touches, specs));
  write(root, 'src/value.txt', 'before\n');
  git(root, 'add', 'docs', 'src');
  git(root, 'commit', '-qm', 'Planned project');
  assert.equal(pm('approve', '--approver', 'Ben').status, 0);
  git(root, 'add', 'docs/approval.json');
  git(root, 'commit', '-qm', 'Approved project');
  assert.equal(pm('claim', '--story', storyRel).status, 0);
  git(root, 'add', storyRel);
  git(root, 'commit', '-qm', 'Claim story');
  git(root, 'checkout', '-qb', 'pm/S1-1-value');
  if (advanceSubmodule) {
    write(dependency, 'value.txt', 'dependency v2\n');
    git(dependency, 'add', 'value.txt');
    git(dependency, 'commit', '-qm', 'Dependency v2');
    const moduleRoot = path.join(root, 'vendor/dependency');
    git(moduleRoot, 'fetch', '-q', 'origin');
    git(moduleRoot, 'checkout', '-q', git(dependency, 'rev-parse', 'HEAD'));
    git(root, 'add', 'vendor/dependency');
    git(root, 'commit', '-qm', 'Advance story dependency');
  }
  if (preexistingDirty) write(root, 'src/preexisting.txt', 'uncommitted user bytes\n');
  write(root, '.deliver/task.json', {
    id: 'S1-1', objective: 'Change the value.', acceptance: [{ id: 'AC-1', text: criterion }],
    read_paths: readPaths, touches, commands: { test: gateCommand }, specs,
  });
  const initialized = run('init', '--mode', 'quick');
  assert.equal(initialized.status, 0, initialized.stdout);
  const runId = initialized.json.run_id;
  const started = run('start', '--run', runId, '--task', '.deliver/task.json', '--builder', 'builder', '--story', storyRel);
  assert.equal(started.status, 0, started.stdout);
  for (const status of ['building', 'built', 'in-review']) assert.equal(pm('transition', '--run', runId, '--to', status).status, 0);
  write(root, 'src/value.txt', 'integrated\n');
  const prepared = run('commit-prepare', '--run', runId);
  assert.equal(prepared.status, 0, prepared.stdout);
  git(root, 'add', '-A', '--', ...prepared.json.preparation.paths);
  git(root, 'commit', '-qm', 'Candidate C');
  const candidate = git(root, 'rev-parse', 'HEAD');
  assert.equal(run('commit-adopt', '--run', runId, '--token', prepared.json.preparation.token, '--commit', candidate).status, 0);
  const checked = run('check', '--run', runId);
  assert.equal(checked.status, 0, checked.stdout);
  assert.equal(run('gate', '--run', runId, '--name', 'test', '--command', gateCommand).status, 0);
  write(root, '.deliver/review.json', {
    status: 'PASS', findings: [], panel: { snapshot_hash: checked.json.snapshot_hash, members: [
      { lens: 'code-integrity-reviewer', reviewer: 'reviewer', verdict: sourceConcern ? 'CONCERNS' : 'PASS', snapshot_hash: checked.json.snapshot_hash,
        findings: sourceConcern ? [{ severity: 'minor', message: 'Keep the source C concern visible.', resolved: false }] : [] },
    ] },
  });
  assert.equal(run('review', '--run', runId, '--snapshot', checked.json.snapshot_hash, '--reviewer', 'reviewer', '--receipt', '.deliver/review.json').status, 0);
  write(root, '.deliver/verification.json', { criteria: [{ id: 'AC-1', status: 'PASS', evidence: 'The test gate passed at candidate C.' }] });
  const selfVerified = run('verify', '--run', runId, '--snapshot', checked.json.snapshot_hash, '--verifier', 'reviewer', '--results', '.deliver/verification.json');
  assert.notEqual(selfVerified.status, 0);
  assert.match(selfVerified.stdout, /verifier must differ from reviewer/i);
  assert.equal(run('verify', '--run', runId, '--snapshot', checked.json.snapshot_hash, '--verifier', 'verifier', '--results', '.deliver/verification.json').status, 0);
  assert.equal(run('finish', '--run', runId).status, 0);
  git(root, 'worktree', 'add', '-q', integration, 'main');
  if (withSubmodule && initializeIntegrationSubmodule) {
    git(integration, '-c', 'protocol.file.allow=always', 'submodule', 'update', '--init', '--recursive', '-q');
  }
  return { root, integration, dependency, leafDependency, runId, runFile: path.join(root, '.deliver/runs', `${runId}.json`), candidate };
}

function integrationCall(f, ...args) { return call(f.integration, pmCli, ...args); }

function mutateRecord(f, state, command, ...args) {
  const result = integrationCall(f, command, '--integration', state.file, '--expected-record', state.hash, ...args);
  assert.equal(result.status, 0, result.stdout);
  state.hash = result.json.hash;
  state.record = result.json.record;
  return result.json.result;
}

test('local C/M/P/E/H closure retains current identity, counters and upstream handoff state', (t) => {
  const f = finishedCandidate(t, { sourceConcern: true });
  const prepared = integrationCall(f, 'integrate-prepare', '--run', f.runFile, '--verification-report');
  assert.equal(prepared.status, 0, prepared.stdout);
  const state = { file: prepared.json.file, hash: prepared.json.hash, record: prepared.json.record };
  assert.equal(state.record.reporting, 'requested');
  assert.equal(readStory(f.root, storyRel).execution.status, 'in-review');
  const resumed = integrationCall(f, 'integrate-prepare', '--run', f.runFile, '--verification-report');
  assert.equal(resumed.status, 0, resumed.stdout);
  assert.equal(resumed.json.resumed, true);
  assert.equal(resumed.json.hash, state.hash);
  assert.equal(resumed.json.record.integration.token, state.record.integration.token);

  git(f.integration, 'merge', '--no-ff', '--no-edit', f.candidate);
  const merge = git(f.integration, 'rev-parse', 'HEAD');
  mutateRecord(f, state, 'integrate-adopt', '--token', state.record.integration.token, '--commit', merge);
  const gate = mutateRecord(f, state, 'integrate-gate', '--name', 'test');
  assert.equal(gate.status, 'PASS');
  write(f.integration, '.deliver/integration-review.json', {
    status: 'PASS', findings: [], panel: { snapshot_hash: state.record.evidence.snapshot_hash, members: [
      { lens: 'code-integrity-reviewer', reviewer: 'm-reviewer', verdict: 'CONCERNS', snapshot_hash: state.record.evidence.snapshot_hash,
        findings: [{ severity: 'minor', message: 'Retain this minor integration concern.', resolved: false }] },
    ] },
  });
  mutateRecord(f, state, 'integrate-review', '--reviewer', 'm-reviewer', '--receipt', '.deliver/integration-review.json');
  write(f.integration, '.deliver/integration-verification.json', {
    criteria: [{ id: 'AC-1', status: 'PASS', evidence: 'The declared gate passed against actual M.' }],
  });
  mutateRecord(f, state, 'integrate-verify', '--verifier', 'm-verifier', '--results', '.deliver/integration-verification.json');
  mutateRecord(f, state, 'integrate-finalize');

  const reportingContract = structuredClone(state.record);
  const droppedReporting = structuredClone(state.record);
  droppedReporting.reporting = 'skipped';
  droppedReporting.reporting_requested = false;
  write(f.integration, path.relative(f.integration, state.file), droppedReporting);
  const refusedDrop = integrationCall(f, 'close-prepare', '--integration', state.file,
    '--expected-record', sha256(canonical(droppedReporting)));
  assert.notEqual(refusedDrop.status, 0);
  assert.match(refusedDrop.stdout, /invalid local integration record/);
  write(f.integration, path.relative(f.integration, state.file), reportingContract);

  const report = mutateRecord(f, state, 'report-prepare');
  const validRecord = structuredClone(state.record);
  const tampered = structuredClone(state.record);
  tampered.report.pending.writes[0].after += 'Unproven claim.\n';
  tampered.report.pending.writes[0].hash = sha256(tampered.report.pending.writes[0].after);
  write(f.integration, path.relative(f.integration, state.file), tampered);
  const refusedResume = integrationCall(f, 'report-prepare', '--integration', state.file,
    '--expected-record', sha256(canonical(tampered)));
  assert.notEqual(refusedResume.status, 0);
  assert.match(refusedResume.stdout, /no longer matches finalized evidence/i);
  write(f.integration, path.relative(f.integration, state.file), validRecord);
  const checklist = report.writes.find((item) => item.path.includes('checklists')).path;
  fs.unlinkSync(path.join(f.integration, checklist));
  const recoveredReport = mutateRecord(f, state, 'report-prepare');
  assert.equal(recoveredReport.token, report.token);
  assert.equal(fs.existsSync(path.join(f.integration, checklist)), true);
  git(f.integration, 'add', '--', ...report.writes.map((item) => item.path));
  git(f.integration, 'commit', '-qm', 'Verification report P');
  mutateRecord(f, state, 'report-adopt', '--token', report.token, '--commit', git(f.integration, 'rev-parse', 'HEAD'));
  const reportText = fs.readFileSync(path.join(f.integration, `docs/verification/S1-1.md`), 'utf8');
  assert.match(reportText, new RegExp(`Candidate C: ${f.candidate}`));
  assert.match(reportText, new RegExp(`Integrated M: ${merge}`));
  assert.match(reportText, /Retain this minor integration concern/);
  assert.match(reportText, /Keep the source C concern visible/);
  assert.doesNotMatch(reportText, /Verification report P/);

  const adoptedReport = structuredClone(state.record);
  const bypassedReport = structuredClone(state.record);
  bypassedReport.report.commit = bypassedReport.integration.commit;
  write(f.integration, path.relative(f.integration, state.file), bypassedReport);
  const refusedBypass = integrationCall(f, 'close-prepare', '--integration', state.file,
    '--expected-record', sha256(canonical(bypassedReport)));
  assert.notEqual(refusedBypass.status, 0);
  assert.match(refusedBypass.stdout, /report adopted commit proof is invalid/i);
  write(f.integration, path.relative(f.integration, state.file), adoptedReport);

  const closure = mutateRecord(f, state, 'close-prepare');
  git(f.integration, 'add', '--', storyRel);
  git(f.integration, 'commit', '-qm', 'Story closure E');
  const closureCommit = git(f.integration, 'rev-parse', 'HEAD');
  mutateRecord(f, state, 'close-adopt', '--token', closure.token, '--commit', closureCommit);
  const mergedStory = readStory(f.integration, storyRel);
  assert.equal(mergedStory.execution.status, 'merged');
  assert.equal(mergedStory.execution.owner, readStory(f.root, storyRel).execution.owner);
  assert.equal(mergedStory.execution.rounds, 0);
  assert.match(mergedStory.text, new RegExp(merge));

  const adoptedClosure = structuredClone(state.record);
  const falseClosure = structuredClone(state.record);
  falseClosure.closure.proof.parent = falseClosure.integration.commit;
  write(f.integration, path.relative(f.integration, state.file), falseClosure);
  const refusedHandoff = integrationCall(f, 'handoff-prepare', '--integration', state.file,
    '--expected-record', sha256(canonical(falseClosure)), '--next', 'Start the next ready story.');
  assert.notEqual(refusedHandoff.status, 0);
  assert.match(refusedHandoff.stdout, /closure adopted commit proof is invalid/i);
  write(f.integration, path.relative(f.integration, state.file), adoptedClosure);

  const handoff = mutateRecord(f, state, 'handoff-prepare', '--next', 'Start the next ready story.');
  git(f.integration, 'add', '--', handoff.writes[0].path);
  git(f.integration, 'commit', '-qm', 'Handoff H');
  const handoffCommit = git(f.integration, 'rev-parse', 'HEAD');
  mutateRecord(f, state, 'handoff-adopt', '--token', handoff.token, '--commit', handoffCommit);
  const handoffText = fs.readFileSync(path.join(f.integration, handoff.writes[0].path), 'utf8');
  assert.match(handoffText, new RegExp(`BASE_COMMIT: ${closureCommit}`));
  assert.match(handoffText, /OPEN_FINDINGS:[\s\S]*Retain this minor integration concern/);
  assert.match(handoffText, /OPEN_FINDINGS:[\s\S]*Keep the source C concern visible/);
  assert.notEqual(handoffCommit, closureCommit);
  assert.equal(upstreamInspect(f.integration).handoff.current, true);
  assert.equal(upstreamExecution(fs.readFileSync(path.join(f.integration, storyRel), 'utf8')).status, 'merged');
});

test('merge adoption refuses altered M and finish alone leaves the claim active', (t) => {
  const f = finishedCandidate(t);
  assert.equal(readStory(f.root, storyRel).execution.status, 'in-review');
  const prepared = integrationCall(f, 'integrate-prepare', '--run', f.runFile);
  assert.equal(prepared.status, 0, prepared.stdout);
  write(f.integration, 'src/unreviewed.txt', 'extra\n');
  git(f.integration, 'add', 'src/unreviewed.txt');
  git(f.integration, 'commit', '-qm', 'Unexpected integration content');
  const rejected = integrationCall(f, 'integrate-adopt', '--integration', prepared.json.file,
    '--expected-record', prepared.json.hash, '--token', prepared.json.record.integration.token,
    '--commit', git(f.integration, 'rev-parse', 'HEAD'));
  assert.notEqual(rejected.status, 0);
  assert.match(rejected.json.error, /no-ff merge/);
  const record = JSON.parse(fs.readFileSync(prepared.json.file, 'utf8'));
  assert.equal(record.integration.status, 'prepared');
  assert.equal(readStory(f.root, storyRel).execution.status, 'in-review');
});

test('bound source-only dirt requires fresh M evidence without mutating C', (t) => {
  const f = finishedCandidate(t, { preexistingDirty: true });
  const prepared = integrationCall(f, 'integrate-prepare', '--run', f.runFile);
  assert.equal(prepared.status, 0, prepared.stdout);
  const state = { file: prepared.json.file, hash: prepared.json.hash, record: prepared.json.record };
  assert.equal(state.record.evidence.source_reusable, false);
  assert.deepEqual(state.record.evidence.reuse_mismatches, ['src/preexisting.txt']);
  git(f.integration, 'merge', '--no-ff', '--no-edit', f.candidate);
  mutateRecord(f, state, 'integrate-adopt', '--token', state.record.integration.token, '--commit', git(f.integration, 'rev-parse', 'HEAD'));
  mutateRecord(f, state, 'integrate-gate', '--name', 'test');
  const missingFresh = integrationCall(f, 'integrate-finalize', '--integration', state.file, '--expected-record', state.hash);
  assert.notEqual(missingFresh.status, 0);
  assert.match(missingFresh.stdout, /require fresh independent M review and verification/i);
  write(f.integration, '.deliver/integration-review.json', {
    status: 'PASS', findings: [], panel: { snapshot_hash: state.record.evidence.snapshot_hash, members: [
      { lens: 'code-integrity-reviewer', reviewer: 'fresh-reviewer', verdict: 'PASS', snapshot_hash: state.record.evidence.snapshot_hash, findings: [] },
